/* Question bank PA test (English convenience translation), Wft Consumer Credit. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["consumptief-krediet"] = [
["What characterises revolving credit?", [["A credit limit within which the consumer can again draw what has been repaid", "With revolving credit, repayments free up borrowing room again up to the agreed limit."], ["A fixed loan amount that is repaid in a fixed number of instalments", "That describes a personal loan; repaid amounts cannot be drawn again there."], ["A loan under which the item only becomes the consumer's property after the last instalment", "That is hire purchase; with revolving credit money is borrowed, rather than an item bought in instalments."], ["A credit that can only be drawn via a credit card linked to it", "A credit card may be linked to a revolving credit, but that is not a feature of every revolving credit."]], "1h.3"],
["What is characteristic of a personal loan?", [["A fixed amount, a fixed term and usually a fixed interest rate", "With a personal loan it is determined in advance how much is borrowed and in how many instalments it is repaid."], ["A variable limit that the consumer can raise themselves", "A limit within which funds can be drawn again belongs to revolving credit, not to the personal loan."], ["An interest-free loan that is repaid within three months", "That resembles deferred payment (BNPL); a personal loan has a longer term and carries interest."], ["A loan secured on a home, with interest deductibility", "A loan with a mortgage right on the home is mortgage credit, not a personal loan."]], "1h.3"],
["Esther Bakker (47) works as a doctor's assistant and took out a personal loan of €15,000.00 five years ago for a new kitchen. She has recently received an inheritance of €6,000.00. She wants to use that amount to make an extra repayment in order to save interest. Next year she may want to buy another car and then draw the repaid amount again. What is correct?", [["Amounts repaid on a personal loan cannot be drawn again", "A personal loan is a fixed-term credit; borrowing again requires a new credit application."], ["She can draw the repaid amount as long as the term has not expired", "Drawing within a limit is only possible with revolving credit, not with a fixed-term loan."], ["She may not make an extra repayment because the term is fixed", "The consumer always has the right to repay early, in full or in part."], ["The lender must automatically make the repaid part available as a new limit", "There is no obligation to convert a fixed-term loan into a limit that can be drawn."]], "1h.3"],
["What is the difference between hire purchase and purchase by instalments?", [["With hire purchase, ownership only passes after payment of the last instalment", "With hire purchase the seller remains the owner until everything is paid; with purchase by instalments, ownership passes immediately."], ["With hire purchase, ownership passes immediately on delivery", "This is precisely the feature of purchase by instalments, not of hire purchase."], ["Hire purchase is only possible for immovable property such as homes and business premises", "In the consumer market, hire purchase actually occurs with movable goods such as cars and appliances."], ["With hire purchase, the consumer never pays interest or costs", "With hire purchase too, a charge for credit may be built into the instalments."]], "1h.3"],
["What is, as a rule, characteristic of private lease of a car?", [["A fixed monthly payment for use; the consumer does not become the owner", "With private lease the consumer rents the car for a fixed period; the lease company remains the owner."], ["The consumer automatically becomes the owner of the car after the last instalment", "Automatic transfer of ownership fits hire purchase or finance lease, not ordinary private lease."], ["The consumer bears all maintenance and insurance costs separately", "With private lease, maintenance and insurance are usually included in the monthly amount."], ["Private lease is a form of mortgage credit in which the car serves as security", "A car cannot serve as security for mortgage credit; private lease is a rental arrangement."]], "1h.2"],
["Why is a private lease contract relevant to the consumer's later mortgage application?", [["The lease obligation counts as a fixed charge and limits borrowing capacity", "A private lease contract is registered with BKR (Dutch credit registration bureau) and counts as a financial obligation in the mortgage assessment."], ["Private lease is not registered and therefore plays no role", "Private lease contracts have been registered with BKR for some years now and are therefore visible to lenders."], ["The lease car may serve as additional security for the mortgage", "The car is owned by the lease company and cannot serve as security for the mortgage."], ["The lease amount is tax deductible in box 1 and therefore increases the assessment income", "Private lease instalments are not deductible for a private individual and do not increase income."]], "1h.5"],
["What is buy now pay later (BNPL)?", [["Paying afterwards or in instalments, often without interest if paid on time", "BNPL lets the consumer pay later or in instalments; costs usually only arise on late payment."], ["A form of saving in which the consumer first saves and then buys", "With BNPL the consumer buys first and pays later, which is precisely a form of credit."], ["A revolving credit with a limit permanently attached to the shop's credit card", "BNPL is usually tied to a specific purchase, not to a limit that can be drawn."], ["A payment method in which the seller collects the full amount in advance", "With prepayment there is no deferral of payment and therefore no credit."]], "1h.2"],
["What is an authorised overdraft?", [["A previously agreed facility to go into the red on the current account up to a limit", "With an authorised overdraft, the bank has agreed a credit limit on the current account with the customer."], ["A negative balance that the bank tacitly allows without any prior agreement with the customer", "A tacitly accepted overdraft without agreement, or beyond the agreed amount, is called an overrun."], ["A loan with a fixed term that is paid out into the current account", "That is a personal loan; payment into the current account does not make it an overdraft."], ["A payment arrears on the instalments of a personal loan", "Arrears on a loan are not an overdraft on a current account."]], "1h.3"],
["Kees de Vries (34) is a warehouse employee and has not agreed an overdraft facility with his bank. At the end of the month the rent is debited from his account while his salary has not yet arrived. His balance consequently goes €400.00 negative. The bank nevertheless executes the payment and charges interest on the shortfall. What is this form of credit called?", [["An overrun", "A tacitly accepted negative balance without an agreed limit, or beyond the limit, is called an overrun."], ["An authorised overdraft", "That requires a previously agreed limit, which is absent here."], ["A personal loan", "No loan amount with a fixed term has been agreed."], ["Hire purchase", "Hire purchase concerns the purchase of an item in instalments, not a negative balance."]], "1h.3"],
["When is there consumer credit within the meaning of the Financial Supervision Act (Wft)?", [["In the case of credit to a natural person acting outside their profession or business", "The Wft protects the consumer; credit for private purposes to a natural person falls within it."], ["In the case of any credit to a natural person, even if it is intended for their sole proprietorship", "Credit that an entrepreneur takes out for their business is business credit and not consumer credit."], ["Only in the case of credit provided by a bank holding a banking licence", "Other credit providers holding a Wft licence also provide consumer credit."], ["Only in the case of credit with a term of more than five years", "The term does not determine whether something is consumer credit."]], "1a.1"],
["What is a linked credit agreement?", [["A credit that serves only for a specific purchase and thereby forms a unit with it", "For example, a loan via the car dealer for that car: the purchase and the credit are connected, with consequences for withdrawal and defences."], ["A credit that is linked to a savings account of the consumer", "A link to a savings account does not make a credit linked in this sense."], ["A credit that two partners take out together, each being jointly and severally liable", "Borrowing jointly concerns liability, not the connection between the purchase and the credit."], ["A credit that has been refinanced from another lender", "Refinancing does not make a credit linked to a purchase agreement."]], "1a.2"],
["Youssef (29) orders a television costing €1,200.00 from an online shop. At checkout he chooses to pay in instalments through a loan that the online shop arranges with a lender especially for this purchase. After five days he changes his mind. He withdraws from the purchase within the statutory cooling-off period and sends the television back. What is, in principle, the consequence for the loan?", [["The linked credit also ends, without a fine", "With a linked credit agreement, the withdrawal from the purchase carries through: the consumer is no longer bound by the credit either."], ["The credit continues in full until the end of its term", "Because the purchase and the credit form a commercial unit, the credit does not simply continue to exist."], ["The consumer must pay a fine equal to all the remaining interest", "Such a fine does not fit the ending of a linked credit after the purchase has lapsed."], ["The credit is automatically converted into a revolving credit", "There is no rule that converts the credit into another credit product."]], "1f.1"],
["Who must assess the consumer's creditworthiness before a consumer credit is concluded?", [["The credit provider", "The statutory duty to prevent over-indebtedness lies with the provider, even if an intermediary is involved."], ["Only the intermediary", "An intermediary gathers information and advises, but the provider's duty to assess remains."], ["Stichting BKR (the BKR foundation)", "BKR registers credits but does not assess applications."], ["The AFM as supervisor", "The AFM supervises compliance but does not assess individual credit applications."]], "1b.2"],
["Mark de Wit (44) is married and wants to buy a €3,000.00 sofa set on instalments in a home furnishings shop. His wife knows nothing about this. The shop arranges the purchase on instalments itself. A month later his wife finds the agreement and does not agree with it. What is correct?", [["Mark needed her consent; without it she can annul the purchase", "For a purchase on instalments a spouse needs the other's consent; if it is lacking, the other spouse can annul the agreement."], ["Consent is only needed if the amount exceeds €10,000.00", "The consent requirement has no amount threshold; it depends on the type of agreement."], ["Consent is not needed, because the law only requires it for suretyship", "Besides suretyship, the consent requirement also applies, among other things, to purchase on instalments."], ["His wife can only object if they are married in community of property", "The consent requirement applies to married persons regardless of the matrimonial property regime."]], "1b.1"],
["Which data source must a credit provider in the Netherlands consult on an application for consumer credit?", [["BKR's credit registration system (CKI)", "Providers must consult a credit registration system; in the Netherlands that is the CKI of Stichting BKR."], ["The Land Registry (Kadaster) and the public registers", "The Kadaster registers immovable property and mortgage rights, not consumer credits."], ["The UWV policy register", "The policy register contains income data, but is not the mandatory credit registration system."], ["Only the Central Insolvency Register", "The insolvency register may be useful in addition, but does not replace the BKR check."]], "1b.3"],
["What are the lending standards in the VFN Code of Conduct broadly based on?", [["Net income minus housing costs and a standard amount for living expenses", "The VFN standards determine repayment capacity from income, housing costs and standard amounts for living expenses."], ["Solely the gross annual income multiplied by a fixed factor", "A fixed income factor takes no account of housing costs and household circumstances."], ["The market value of the home of the consumer and their partner", "With consumer credit the focus is on ability to pay, not the value of the home."], ["The amount of the consumer's savings balance and investments", "Assets may play a part, but are not the basis of the VFN lending standards."]], "1h.5"],
["Erwin (51) has been under protective administration (beschermingsbewind) since last year because of problematic debts. His administrator manages his income and pays his fixed costs. Erwin wants to apply online himself for a €2,000.00 loan for a scooter. He tells the provider that he is 'simply legally competent'. What is correct for the credit provider?", [["Erwin is legally competent, but his administrator manages his income and assets", "Protective administration relates to the management of property; the administrator must therefore be involved in the application."], ["Erwin is legally incompetent, so every loan is void by operation of law", "Legal incompetence belongs to guardianship (curatele) and minority, not to protective administration."], ["The administration is not relevant, because it only concerns his home", "Protective administration actually concerns his property, such as income and assets."], ["The provider may only lend after prior permission from the AFM", "The AFM does not give permission for individual credits."]], "1c.1"],
["What data does BKR keep in the Central Credit Information System?", [["Current and repaid credits and any payment arrears", "The CKI contains both positive registrations (credits) and negative ones (arrears)."], ["Only credits on which an arrear has arisen", "BKR also registers credits without arrears; these are positive registrations."], ["The consumer's income and assets", "BKR registers credits, not income or asset data."], ["All payments the consumer makes with their debit card or credit card", "Payment data are not passed on to BKR."]], "1b.3"],
["What does an arrears code A in the BKR mean?", [["A payment arrear has been reported", "Code A records that the consumer has not paid as agreed."], ["The credit has been fully repaid and ended", "Full repayment is registered as an end date, not as code A."], ["The consumer has submitted a credit application", "An application is not an arrears code."], ["The credit limit of the credit has been raised", "A limit change is a change to the contract, not an arrear."]], "1b.3"],
["What does a code H in the BKR mean?", [["The reported arrear has been made up (recovery)", "Code H shows that the consumer has caught up on the previously reported arrear."], ["A mortgage loan has been registered", "Mortgages are not shown as code H in the CKI; H is a recovery code."], ["The credit has been called in by the lender", "Calling in is a different special entry from recovery."], ["The consumer has withdrawn from the credit in good time", "Withdrawal is not a BKR code; H stands for recovery."]], "2a.3"],
["Linda and Mark Hoekstra (both 41) have two children and want a €12,000.00 personal loan for a new bathroom. The BKR check shows that Mark still has a revolving credit with a limit of €10,000.00. He says he has not used that credit for years and that the balance is zero. He wants to keep it as a reserve. How is this revolving credit as a rule included in the assessment?", [["As a charge based on a notional monthly instalment on the full limit", "Because the customer can draw the limit at any time, the limit is used for the calculation and not the amount drawn."], ["It does not count, because nothing has been drawn from the limit", "The borrowing room can be used at any time; the undrawn part is therefore not ignored."], ["Only the interest actually paid on the credit counts", "Without drawings there is no interest, but the risk of the limit remains."], ["The credit actually increases the customer's borrowing capacity because it acts as a buffer", "An open limit reduces the room for new credit."]], "1h.5"],
["Romy Kuiper (26) applies for a €7,500.00 personal loan for a second-hand car. She has a permanent contract as a nurse. The credit provider consults BKR and sees an arrears code on an earlier credit. On that basis the provider rejects the application. What must the provider do towards Romy?", [["Inform the consumer at once and free of charge about the consultation and result", "When an application is rejected on the basis of a database consultation, the consumer must be informed of this so that they can check the data."], ["Say nothing, because the reason for rejection is commercially confidential", "Precisely when an application is rejected on the basis of a registration, the consumer is entitled to that information."], ["Register the consumer with the municipal debt assistance service without consultation", "A rejection is no reason to register someone with debt assistance without their consent."], ["Have the BKR registration removed and then fully reassess the application", "The provider may not have a correct registration removed in order to remedy a rejection."]], "3d.1"],
["Peter Smit (52) hears, on a credit application, that there is an arrears code in his name in the BKR. According to Peter this is wrong: he has always paid his previous loan on time and can prove that with bank statements. He is angry and wants the registration gone as soon as possible. He asks his adviser what he can best do. Which step is the most obvious?", [["Request access and ask the registering lender to correct it", "The registering lender is responsible for accuracy; the consumer has the right of access and correction."], ["Ask the AFM to delete the registration from the system immediately", "The AFM does not decide on individual BKR registrations."], ["Take out a new loan so that the old registration is overwritten", "A new loan does not remove an existing registration and increases the debt burden."], ["Ask the Dutch Tax Administration for a statement about his income", "The Dutch Tax Administration is not involved in credit registrations."]], "1b.3"],
["Monique Verbeek (38) has had a revolving credit with a limit of €5,000.00 for three years. She has recently started working part-time to care for her mother. She now wants the limit raised to €15,000.00 for a different car. She assumes this is a formality, because she has always paid on time. Must the credit provider reassess her creditworthiness?", [["Yes, a significant increase requires a new assessment", "A significant increase in the credit amount requires a new creditworthiness assessment; moreover, her income has fallen."], ["No, the earlier assessment when the credit was taken out remains valid", "Her situation has changed since the credit was taken out; an old assessment is not sufficient for a significant increase."], ["Only if Monique herself expressly asks for a new assessment", "The duty to assess is an obligation of the provider, not a choice for the consumer."], ["No, because she has never had a payment arrear", "Even without an arrear, a significant increase requires a new assessment."]], "1b.2"],
["Rik Mulder (44) has been a self-employed painter for six years. He lives with his girlfriend and wants a €18,000.00 personal loan to renovate their loft. Last quarter he had record turnover. He proposes to supply only the figures for that quarter. Which income is relevant for the assessment?", [["A sustainable income, supported by figures over several years", "For entrepreneurs the provider looks at income over several years to obtain a reliable picture."], ["The turnover of the last quarter, extrapolated to a year", "Turnover is not income, and one good quarter does not give a sustainable picture."], ["The income Rik expects to earn after the renovation", "An unsubstantiated expectation is not a solid basis for the assessment."], ["None, because self-employed persons are excluded from consumer credit", "Self-employed persons can simply apply for consumer credit for private purposes."]], "2c.3"],
["Why does a credit provider ask about the consumer's housing costs on an application?", [["Housing costs are a fixed charge that directly limits repayment capacity", "In the lending standards, housing costs are deducted from income before the room for credit is calculated."], ["In order to be able to use the home as security", "With consumer credit the home is generally not taken as security."], ["To determine whether the consumer receives rent allowance", "Allowances may be relevant to income, but housing costs are not asked about for that purpose."], ["Because the amount of the housing costs determines the maximum cost of credit of the loan", "The maximum cost of credit is independent of the consumer's housing costs."]], "1h.5"],
["Which document must the consumer receive before a consumer credit is concluded in order to be able to compare offers?", [["The Standard European Consumer Credit Information (SECCI)", "The SECCI is the standardised information form for consumer credit and makes comparison possible."], ["The European Standardised Information Sheet (ESIS)", "The ESIS is the European information form for mortgage credit."], ["The key information document (KID) under PRIIPs", "The KID belongs to packaged investment and insurance products under PRIIPs."], ["The Uniform Pension Overview (UPO) from the pension provider", "The UPO is a pension overview and has nothing to do with credit."]], "1a.3"],
["What does the annual percentage rate of charge (APR) express?", [["The total cost of the credit as an annual percentage of the credit amount", "The APR includes interest and all other mandatory costs and makes credits comparable with one another."], ["Only the nominal debit interest rate calculated on an annual basis on the outstanding credit", "The debit interest rate is just one component; the APR also includes other mandatory costs."], ["The percentage of net income that goes to the loan each month", "That is a housing-cost-ratio or burden concept, not the APR."], ["The maximum interest rate that the AFM sets every year for consumer credit", "The APR is a feature of a specific credit, not a maximum set by the AFM."]], "1h.6"],
["Which costs are not included in the total cost of the credit for the calculation of the APR?", [["Costs on non-compliance, such as fines for a payment arrear", "The APR assumes normal compliance; costs on default fall outside it."], ["The interest the consumer owes on the credit drawn", "Interest is the main component of the cost of the credit."], ["Mandatory arrangement fees that the lender charges at the outset", "Costs that the consumer is obliged to pay in order to obtain the credit are included."], ["Premium of an insurance that is mandatory in order to obtain the credit", "A mandatory ancillary service as a condition for the credit belongs to the costs."]], "1h.6"],
["Which warning is mandatory in the Netherlands in advertising for consumer credit?", [["'Let op! Geld lenen kost geld' (Caution! Borrowing money costs money)", "This fixed sentence must be clearly visible or audible in credit advertising."], ["'Borrowing is a risk, ask the AFM for information'", "This is not a legally prescribed text."], ["'Past performance is no guarantee'", "This text belongs to investment advertising, not to credit."], ["'Let op! Rente kan stijgen' (Caution! Interest rates may rise)", "This is not a prescribed warning sentence for credit advertising."]], "1a.2"],
["A credit provider advertises an interest rate for a personal loan. What must the advertisement then also contain?", [["Standard information with a representative example, including the APR", "Anyone who states an interest rate or other cost figure in advertising must give the standard information with a representative example."], ["An overview of all complaints received in the past year", "Complaints data do not belong in credit advertising."], ["The name and registration number of the adviser handling the matter", "Advertising does not have to name a personal adviser."], ["The name and registration number of the adviser handling the matter personally", "The AFM does not approve products or advertising in advance."]], "1a.2"],
["May a consumer ask for a draft of the credit agreement before a consumer credit is concluded?", [["Yes, they can obtain the draft agreement free of charge", "Unless the provider is unwilling to grant the credit, the consumer is entitled to a draft free of charge."], ["No, the draft agreement is only provided to them at signing", "The law actually gives the consumer the right to receive a draft in advance."], ["Yes, but only on payment of administration costs", "The draft must be provided free of charge."], ["Only if the credit amount is higher than the lending standard", "The right to a draft does not depend on the size of the credit."]], "1a.3"],
["What does the duty to explain of the credit provider or intermediary entail?", [["Explaining to the consumer so that they can assess whether the credit suits them", "In addition to the SECCI, the consumer must receive an explanation of the features, consequences and risks, including those of non-payment."], ["Only sending the SECCI form, without giving any further explanation", "The form alone is insufficient; an explanation is also required."], ["Referring the consumer to the AFM website for an explanation", "Referring does not replace the provider's own explanation."], ["Having the consumer sign that they expressly do not want an explanation", "The duty to explain cannot simply be signed away."]], "1a.3"],
["What information about payment arrears must be included in the pre-contractual information on consumer credit?", [["The consequences of failing to make payments, such as extra costs and registration", "The consumer must know in advance what happens if they do not pay, so that they can assess the risk."], ["The name and address of the debt collection agency the lender engages in the event of arrears", "That is not a mandatory part of the pre-contractual information."], ["The number of customers with a payment arrear at the provider", "The provider's statistics do not belong in the pre-contractual information."], ["None; arrears are only discussed when they actually arise", "The consequences of arrears must actually be stated in advance."]], "1a.3"],
["Gerrit Bos (58) has a revolving credit with a limit of €4,000.00. As a result of a series of unexpected expenses, €5,500.00 has been outstanding for well over two months. The lender has permitted the drawings above the limit. Gerrit has not yet received any notification about this. What must the lender do?", [["Inform the consumer about the overrun, the interest and the costs", "In the case of a significant overrun lasting longer than a month, the consumer must be informed without delay."], ["Let the overrun continue tacitly without telling the consumer anything", "The consumer must actually be informed in order to prevent further build-up of debt."], ["Automatically raise the limit to the amount drawn", "A limit increase requires a new creditworthiness assessment and cannot be done automatically."], ["Report the credit and the overrun to the AFM immediately", "Individual overruns are not reported to the AFM."]], "1a.3"],
["Sandra Willems (36) wants to borrow €10,000.00 to furnish her new rented home. She receives two quotes with the same term. Loan A has a lower debit interest rate, but arrangement fees are added. Loan B has a slightly higher interest rate and no arrangement fees. How does Sandra compare the quotes most accurately?", [["Compare the APR and the total amount payable of both loans", "The APR and the total amount take into account both interest and costs and show what the loan really costs the customer."], ["Always choose the loan with the lowest annual debit interest rate", "The lowest interest rate can still turn out more expensive because of arrangement fees."], ["Always choose the loan with the lowest monthly instalment for the customer", "A low monthly instalment can be the result of a longer term and therefore higher total costs."], ["Compare only the term and the end date of both loans with one another", "The term in itself says nothing about the costs."]], "1h.6"],
["How long is the withdrawal period for a consumer credit?", [["Fourteen calendar days", "The consumer can withdraw from the credit agreement within fourteen calendar days without giving reasons."], ["Three working days", "Three days is the cooling-off period for the purchase of a home, not for credit."], ["Twenty-one calendar days", "The withdrawal period for consumer credit is fourteen calendar days, not twenty-one."], ["Seven working days", "A period of seven working days does not apply to consumer credit."]], "1f.1"],
["When does the withdrawal period for a consumer credit start to run?", [["On conclusion, or later if the consumer only receives the information afterwards", "The period only starts once the consumer has both the agreement and the mandatory information."], ["On the day the first monthly instalment is debited", "The first payment does not determine the start of the period."], ["On the day the BKR registration of the new credit first becomes visible", "BKR registration is separate from the withdrawal period."], ["On the day the consumer submits the credit application", "At the time of the application there is not yet an agreement that can be withdrawn from."]], "1f.1"],
["Ilse Jansen (31) took out a €9,000.00 personal loan on Monday; the amount is in her account a day later. A week later she decides to postpone the renovation after all. She withdraws from the loan in good time and in writing. She has not yet spent the money. What must she do now?", [["Repay the borrowed amount and accrued interest within thirty days", "After withdrawal the consumer repays the principal and the accrued interest, without a fine."], ["Repay nothing until the end of the original term of the loan", "Withdrawal ends the credit; the money must be repaid."], ["Pay the lender a fine of a fixed percentage of the credit amount", "No fine is owed on withdrawal."], ["Pay only the arrangement fees and keep the borrowed money", "The borrowed money must be repaid; withdrawing is not the same as borrowing at no cost."]], "1f.1"],
["Does a consumer have the right to repay a personal loan early?", [["Yes, fully or partly, at most for a capped fee", "Early repayment is a right; the lender may at most charge a limited fee, capped by law."], ["No, only if the lender gives prior permission for it", "The consumer has this right regardless of the lender's permission."], ["Only after half of the loan's term has elapsed", "There is no waiting period for early repayment."], ["Yes, but only in full and in one go, not in part", "Partial early repayment is also permitted."]], "1i.4"],
["When may a lender not charge a fee on early repayment of a consumer credit?", [["If the repayment falls in a period in which the interest rate is variable", "The fee only covers a loss in the case of a fixed interest rate; with a variable rate no fee is permitted."], ["If the interest rate is fixed for the entire term of the credit", "Precisely with a fixed interest rate, a limited fee may be charged."], ["If the consumer repays early with their own savings", "The source of the money does not determine whether a fee is allowed."], ["If the remaining term of the credit is longer than one year", "With a remaining term of more than one year, a (slightly higher) fee may actually be charged."]], "1i.4"],
["How can a consumer terminate a revolving credit (credit of indefinite duration)?", [["Free of charge and at any time, with at most one month's notice", "The consumer may always terminate a revolving credit free of charge; a notice period may not be longer than one month."], ["Only after a minimum term of five years has elapsed", "Such a minimum period is not permitted."], ["Only on payment of a termination fee to the lender", "Terminating a revolving credit is free of charge."], ["Only with the prior consent of the lender", "The lender's consent is not needed."]], "1f.1"],
["May a lender suspend the consumer's right to draw on a revolving credit?", [["Yes, if agreed and there are objectively justified grounds", "For example, on suspicion of fraud or a significantly increased risk that the consumer cannot repay."], ["No, the agreed limit must always remain fully available", "Suspension is possible for objectively justified reasons."], ["Yes, at any time and without giving a reason", "An objectively justified ground is needed and the consumer must be informed."], ["Only after the AFM has given prior permission in that specific case", "No AFM permission is needed for suspension in an individual case."]], "1f.1"],
["Where is the maximum cost of credit for consumer credit regulated?", [["In the Credit Charges Decree (Besluit kredietvergoeding)", "This decree sets the maximum that may be charged in costs and interest."], ["In the Temporary Mortgage Credit Regulation (TRHK)", "The TRHK contains lending standards for mortgages, not a maximum cost of credit."], ["In the VFN Code of Conduct", "The code of conduct contains lending standards; the maximum is laid down by law."], ["In BKR's general terms and conditions", "BKR does not set rates or maxima for credits."]], "1a.1"],
["To what is the maximum cost of credit for consumer credit linked?", [["To the statutory interest rate plus fixed percentage points", "The maximum moves with the statutory interest rate, so that it need not be re-set with every interest rate change."], ["To the deposit rate that DNB pays to banks, plus a margin", "The maximum is not linked to a DNB interest rate."], ["To the average mortgage interest rate of the three largest Dutch banks", "Mortgage interest rates are not the basis of the maximum."], ["To the consumer's income and the size of the credit", "The maximum is the same for all consumers and does not depend on income."]], "1h.6"],
["What falls under the cost of credit to which the statutory maximum relates?", [["The interest and all other costs the consumer pays for the credit", "The maximum applies to the total charge, so that it cannot be circumvented with separate costs."], ["Only the nominal interest, excluding arrangement or administration fees", "If only interest counted, the maximum could be evaded with arrangement or administration fees."], ["Only the arrangement fees charged as a lump sum at the start of the credit", "Interest also falls under the cost of credit."], ["Only the costs that arise after the first month of the credit", "The maximum applies to all costs of the credit, from the start."]], "1h.6"],
["A bank charges a high debit interest rate on an overrun on a customer's current account. Does the maximum cost of credit also apply here?", [["Yes, the maximum also applies to overdrafts and overruns", "Even when in the red, the bank may not charge more than the maximum cost of credit."], ["No, only to personal loans", "The maximum is not limited to personal loans."], ["No, current accounts are subject to free pricing", "Credit on a current account also falls under the maximum."], ["Only if the overdraft on the current account lasts longer than a year", "The duration of the overdraft does not determine whether the maximum applies."]], "1h.6"],
["Which act regulates consumer credit insofar as it does not fall under the Wft?", [["The Consumer Credit Act (Wck)", "The Wck continued to exist after the introduction of the Wft for credits that fall outside the Wft regime."], ["The Municipal Debt Assistance Act (Wet gemeentelijke schuldhulpverlening)", "That act concerns the task of municipalities in debt assistance."], ["The Act on the prevention of money laundering and terrorist financing", "The Wwft concerns money laundering, not credit agreements."], ["The Temporary Mortgage Credit Regulation", "The TRHK contains lending standards for mortgage credit."]], "1f.1"],
["What is the consequence of being placed under guardianship (curatele) for entering into a consumer credit?", [["The person is legally incompetent and cannot do so without the guardian", "A person under guardianship is legally incompetent; the guardian acts on their behalf or must cooperate."], ["They remain fully legally competent; only their income is under administration", "That describes protective administration (beschermingsbewind), not guardianship."], ["They may only conclude credits of up to €1,000.00", "No such amount limit exists under guardianship."], ["There is no consequence as long as they have a fixed income themselves", "Income does not change the legal incompetence resulting from guardianship."]], "1b.1"],
["Does a firm that intermediates in consumer credit in principle need an AFM licence?", [["Yes, intermediating in credit is a financial service requiring a licence", "Intermediating in financial products, including credit, is in principle only allowed with a licence or a valid exemption."], ["No, only the provider needs a licence", "A licence requirement also applies in principle to intermediation."], ["Only if the credit is higher than the mortgage limit", "There is no link to a mortgage limit."], ["No, registration with the Chamber of Commerce (KvK) as an intermediary is sufficient", "A KvK registration is not a Wft licence."]], "1a.1"],
["Which body can a consumer turn to with a complaint about a credit provider if the internal complaints procedure offers no solution?", [["Kifid (Dutch Financial Services Complaints Institute)", "Wft firms that provide services to consumers must be affiliated with Kifid."], ["BKR", "BKR handles questions about registrations, but is not a dispute body for credit complaints."], ["The Dutch Data Protection Authority", "The Dutch Data Protection Authority supervises the GDPR (AVG), but does not settle disputes about credits."], ["The Dutch Tax Administration", "The Dutch Tax Administration does not handle disputes between consumers and credit providers."]], "1a.1"],
["Which Wft exam is as a rule required for an adviser who advises consumers on consumer credit?", [["Wft Consumer Credit, in addition to Wft Basic", "For advising on consumer credit, the Consumer Credit module is the professional qualification requirement, with Wft Basic as the foundation."], ["Solely the Wft Mortgage Credit module", "Mortgage credit is a different module that does not replace consumer credit."], ["The Wft Non-life Insurance (Personal) module", "That module concerns non-life insurance."], ["The Wft Pensions module, in addition to Wft Basic", "That module concerns pension advice."]], "1a.1"],
["Which European directive underlies the Dutch consumer credit rules until 20 November 2026?", [["Directive 2008/48/EC (CCD I)", "The first consumer credit directive has been implemented in the Wft and the Dutch Civil Code (BW) and will be replaced by CCD II on 20 November 2026."], ["Directive 2014/17/EU (MCD)", "The MCD concerns mortgage credit."], ["Directive (EU) 2016/97 (IDD)", "The IDD concerns insurance distribution."], ["Directive 2014/65/EU (MiFID II)", "MiFID II concerns investment services."]], "1a.2"],
["Where are the civil-law rules on the credit agreement with a consumer, such as withdrawal and early repayment, largely found?", [["In Book 7 of the Dutch Civil Code (BW)", "The private-law rules from the consumer credit directive are included in a separate title of Book 7 of the BW."], ["In the Municipal Debt Assistance Act", "That act regulates the debt assistance task of municipalities, not the credit agreement."], ["In the General Administrative Law Act (Awb)", "The Awb concerns the relationship between citizens and government."], ["In the Bankruptcy Act", "The Bankruptcy Act concerns insolvency, not the conclusion of credit agreements."]], "1f.1"],
["A shopkeeper offers customers the option to spread a purchase over three instalments within three months, without interest or costs. Why does this generally fall outside the credit regime requiring a licence under the current rules?", [["Interest-free short-term credit with low costs is exempted", "This exemption explains why BNPL has so far largely fallen outside the credit regime; CCD II restricts it."], ["Because the shopkeeper is not a bank and so cannot grant credit", "Non-banks can also offer credit requiring a licence; the type of credit is decisive."], ["Because the purchase amount is below the NHG (National Mortgage Guarantee) cost limit", "A mortgage limit plays no role in consumer credit."], ["Because the consumer themselves asked for the deferral of payment", "Whoever asks for the credit does not determine whether the regime applies."]], "1a.1"],
["From when does the revised Consumer Credit Directive (EU) 2023/2225 apply?", [["20 November 2026", "Member States must apply the new rules from 20 November 2026."], ["1 January 2026", "On that date the CCD II rules did not yet apply."], ["By 20 November 2025", "That was the deadline for transposition into national legislation, not the date of application."], ["1 July 2027", "Application does not begin on that date; it is earlier."]], "1a.2"],
["What is the status of the Dutch implementation of CCD II on the reference date of 15 October 2026?", [["The implementation act is in preparation", "The directive has not yet been fully transposed into Dutch legislation; market parties must nevertheless prepare."], ["The implementation act has applied since 2024", "On the reference date the implementation had not yet been completed."], ["The Netherlands has decided not to implement CCD II", "Member States are obliged to transpose a directive."], ["CCD II works directly as a regulation and does not need to be transposed", "CCD II is a directive and must be transposed into national legislation."]], "1a.2"],
["Which development belongs to CCD II?", [["Buy now pay later and lease with a purchase option come under the credit regime", "CCD II widens the scope to forms that previously fell outside the rules."], ["Mortgage credit will fall under CCD II", "Mortgages remain subject to the Mortgage Credit Directive."], ["The creditworthiness assessment is abolished for credits under €1,000.00", "CCD II actually strengthens the assessment, including for smaller amounts; there is no exemption under €1,000.00."], ["The right of withdrawal lapses for online credit", "The right of withdrawal remains, online as well."]], "1a.2"],
["What does CCD II change about the lower threshold of the scope compared with CCD I?", [["Credits under €200.00 also fall in principle under the directive", "CCD I did not apply to credits under €200.00; CCD II removes that lower threshold, which mainly affects small BNPL credits."], ["The lower threshold is raised to an amount of €1,000.00", "CCD II actually lowers the threshold; small credits come under it."], ["A new lower threshold of €500.00 per credit will apply", "CCD II does not introduce a new lower threshold of €500.00."], ["The CCD I lower threshold remains unchanged under CCD II", "The abolition of the lower threshold is precisely one of the changes."]], "1a.2"],
["What does CCD II provide about the use of data in the creditworthiness assessment?", [["Special categories of personal data and social media data are excluded", "The assessment must rely on relevant, accurate information about income and expenditure, not on sensitive or social media data."], ["All available data, including social media, must be used", "CCD II actually excludes social media data."], ["Only the consumer's own statement may be used", "The provider must verify the information where necessary and may also consult databases."], ["Health data are mandatory for credits with a term of more than ten years", "Health data are special categories of personal data and may not be used."]], "1a.2"],
["What right does the consumer get under CCD II if the creditworthiness assessment is carried out automatically?", [["The right to human intervention, an explanation and to express their own view", "The consumer can ask for a reassessment by a human and obtain an explanation of the assessment."], ["The right to carry out the creditworthiness assessment themselves and supply it", "The assessment remains an obligation of the provider."], ["The right to determine the interest rate and the term of the credit themselves", "The consumer does not obtain the right to set the interest rate."], ["The right to have correct BKR registrations removed immediately", "CCD II gives no right to the removal of correct registrations."]], "1a.2"],
["What does CCD II provide about granting credit if the creditworthiness assessment is negative?", [["In principle the credit may then not be made available", "Credit may only be granted if the assessment shows that the consumer is likely to be able to meet their obligations."], ["The credit may always be granted if the consumer signs for the risk", "A consumer's signature does not make a negative assessment positive."], ["The credit may be granted at a higher interest rate", "A higher interest rate actually increases the risk of over-indebtedness."], ["The credit must then go through an intermediary", "Involving an intermediary does not change the outcome of the assessment."]], "1a.2"],
["What does CCD II provide about unsolicited credit?", [["Credit may not be granted without the consumer's request and consent", "Unsolicited credit and unsolicited limit increases are prohibited in order to prevent over-indebtedness."], ["Unsolicited credit is allowed as long as the interest rate is below the statutory maximum", "A low interest rate does not make unsolicited credit permitted."], ["Unsolicited credit may be granted to existing customers", "Unsolicited credit is not permitted for existing customers either."], ["CCD II leaves the rules on unsolicited credit entirely to the market", "CCD II actually contains an express prohibition on this."]], "1a.2"],
["What obligation does CCD II impose on lenders before they take enforcement measures in the event of payment problems?", [["Where suitable, show reasonable forbearance, e.g. adjusted terms", "CCD II asks for accommodating measures before enforcement, taking the consumer's situation into account."], ["Immediately call in the full claim and hand it over to debt collection", "Calling in immediately without forbearance is contrary to the idea behind CCD II."], ["Write off the outstanding credit in full in all cases", "Write-off is not an obligation; forbearance must, however, be considered."], ["Make the consumer go to court for an arrangement", "Going to court is not a mandatory first step."]], "1a.2"],
["Sanne Jacobs (37) was dismissed after nine years with the same employer because of a reorganisation. She receives a WW (unemployment benefit) and is actively applying for jobs. She wants to borrow €6,000.00 over five years to replace her car. She has no partner and no savings. What is especially important in assessing her benefit?", [["The WW is temporary, while the loan runs for much longer", "The duration of the WW depends on the employment history and is limited; after it ends, income may fall further."], ["The WW continues until the AOW (state pension) age, so the income is sustainable", "The WW is a temporary benefit and does not continue until the AOW age."], ["A WW benefit may by law never count as income", "There is no legal prohibition; the question is whether the income is sustainable enough."], ["Only the amount of the benefit counts; the duration plays no role", "It is precisely the limited duration that is decisive for whether she can continue to pay the instalments."]], "1d.1"],
["An employee with a personal loan falls ill for a long period. What is the main income risk for paying the instalments?", [["After two years of continued payment of wages, their income may fall sharply", "After the period of continued payment of wages during illness, in the case of lasting incapacity for work a WIA (Work and Income according to Labour Capacity Act) assessment follows, often with a lower income."], ["Their wages stop completely on the first day of illness", "The employer must in principle continue to pay wages (in part) for two years during illness."], ["Their loan is written off by operation of law in the event of long-term illness", "Illness has no effect on the existence of the debt."], ["The employer takes over the instalments during illness by law", "There is no legal obligation on the employer to pay employees' loans."]], "1d.2"],
["An online shop works with a BNPL provider that currently still falls under an exemption. What is the most important question for this provider in the run-up to CCD II?", [["Whether the service falls under the credit regime, with licence and assessment", "CCD II brings BNPL under the rules; the Dutch implementation determines the precise obligations."], ["Whether the online shop must apply for a mortgage licence in order to offer this payment method", "BNPL has nothing to do with mortgage credit."], ["Whether the consumer still has a right of withdrawal on the products bought", "The right of withdrawal on the purchase exists independently of CCD II; what matters here is the credit regime."], ["Whether the BNPL provider must take over the shares of the online shop", "CCD II sets no requirements on ownership relationships between shop and provider."]], "1a.2"],
["Which authority in the Netherlands is responsible for debt assistance to residents?", [["The municipality", "Under the Municipal Debt Assistance Act, municipalities must offer debt assistance to residents."], ["The province", "Provinces have no statutory task in debt assistance."], ["The national government via the Dutch Tax Administration", "The Dutch Tax Administration is a creditor, not a debt assistance provider."], ["The AFM", "The AFM is a supervisor and provides no debt assistance."]], "1f.2"],
["What is early warning (vroegsignalering) in the context of debt assistance?", [["Reporting arrears on fixed costs early to the municipality in order to offer help", "Certain creditors such as energy and drinking water companies, health insurers and landlords pass arrears on to the municipality."], ["Automatically registering every purchase by a consumer with BKR", "Early warning concerns arrears, not purchases."], ["Having consumers' credit applications blocked in advance by the AFM", "The AFM does not block individual applications."], ["Warning employers early about their employees' debts", "Early warning runs via the municipality, not via the employer."]], "1f.2"],
["What is the difference between the amicable arrangement and the Wsnp?", [["The amicable arrangement is voluntary; the Wsnp is a statutory debt restructuring via the court", "Only if an amicable arrangement fails can the court admit someone to the Wsnp."], ["The amicable arrangement goes through the court, the Wsnp goes through municipal debt assistance", "It is exactly the other way round: the Wsnp goes through the court."], ["There is no difference; they are two names for the same debt assistance route", "They are two different routes with a different legal basis."], ["The Wsnp is only intended for entrepreneurs with business debts", "Private individuals can also be admitted to the Wsnp."]], "1f.2"],
["Hans Koster (49) is a lorry driver and has a revolving credit with a drawn balance of €8,000.00. His employer goes bankrupt and Hans will soon receive a benefit that is lower than his wages. He phones the lender to say that he probably cannot pay the instalment next month. There is no arrear yet. What is the lender's best first response?", [["Enter into discussion about a suitable payment arrangement and point to debt assistance options", "Early intervention prevents debts from growing; the duty of care requires working with the customer."], ["Temporarily raise the limit so the customer can pay the coming instalments from the credit itself", "New credit to pay existing credit increases the debt burden."], ["Call in the credit immediately before an arrear actually arises", "Calling in immediately without consultation is needlessly harsh and not in the customer's interest."], ["Do nothing until the claim goes to a debt collection agency after a few months", "Waiting lets the debt and costs grow."]], "1i.2"],
["What is the protected income (beslagvrije voet)?", [["The part of income that remains protected from attachment for living expenses", "Creditors may not touch income below this limit."], ["The maximum amount someone may borrow according to the lending standards", "That is a lending standard, not a protected income."], ["The period immediately after taking out a loan during which no attachment may be levied", "The protected income is an amount, not a period of time."], ["The amount above which a credit must be reported to BKR", "That has nothing to do with attachment."]], "1i.5"],
["A consumer is admitted to the Wsnp. What is, in general, the consequence if they comply with all obligations during the term?", [["At the end they can receive a clean slate (schone lei) for the remaining debts", "With the clean slate, the remaining debts can no longer be enforced."], ["All their debts are written off immediately at the start of the scheme", "Discharge only follows at the end, once the obligations have been met."], ["They automatically receive new credit from the municipality afterwards", "The Wsnp does not lead to new credit."], ["Their lender must give them a higher credit limit afterwards", "There is no obligation to provide more credit."]], "1f.2"],
["Adviser Fatima El Amrani speaks with Dennis (33), single and a mechanic. Dennis wants to borrow €5,000.00 in order to 'get everything straight'. During the conversation it emerges that he has arrears with his health insurer and his energy supplier. There are also letters from a debt collection agency. What is appropriate for Fatima?", [["Not advise credit that increases the problems, and point to debt assistance", "The duty of care requires putting the client's interest first, even if that means no credit is granted."], ["Quickly arrange a revolving credit so that the current collection actions stop", "Extra credit alongside existing arrears can put the client deeper into difficulty."], ["Keep the arrears out of the file so that the assessment passes", "Withholding or not recording information is contrary to the duty of care and may be fraud."], ["Advise the client to first ask another provider for a second loan", "A loan elsewhere also increases the debt burden and does not solve the problem."]], "1c.2"],
["Why does a credit provider fall under the Wwft?", [["Because granting credit is a financial service that is vulnerable to money laundering", "Credit providers are Wwft institutions and must carry out customer due diligence and report unusual transactions."], ["Because every entrepreneur who charges interest falls under the Wwft", "Charging interest does not by itself make a firm subject to the Wwft."], ["Because BKR makes this a condition in its general terms and conditions", "The Wwft obligation follows from the law, not from BKR's terms."], ["Because consumer credit falls under the commission ban of the Wft", "The commission ban has nothing to do with the Wwft."]], "1a.1"],
["Bart Hendriks (40) took out a €20,000.00 personal loan two months ago for a camper van. He now presents himself at the credit provider to repay the entire loan in cash. He has the money with him in a sports bag. Asked where the money comes from, he gives a vague answer. What must the credit provider do?", [["Investigate whether this is an unusual transaction and, if necessary, report it to the FIU", "Quick repayment in cash of unclear origin is a signal that calls for investigation and possibly a report."], ["Warn the customer in advance that a report about them may be made", "A duty of confidentiality applies; the customer may not be told about a report."], ["Refuse the repayment and hand the cash straight to the police", "The Wwft calls for investigation and reporting, not for handing over to the police."], ["Do nothing, because early repayment is a statutory right of the customer", "The right to early repayment does not exempt from the Wwft obligations."]], "4a.1"],
["Which element belongs to customer due diligence under the Wwft when entering into a credit relationship?", [["Establishing and verifying identity", "The provider must know who they are doing business with, for example by means of a valid proof of identity."], ["Calculating the APR of the credit", "The APR is pre-contractual information, not customer due diligence."], ["Testing against the VFN lending standards", "That belongs to the creditworthiness assessment, not to the Wwft investigation."], ["Drawing up and providing a SECCI", "The SECCI is an information form, not part of customer due diligence."]], "1a.1"],
["What is the correct order of steps in applying for and granting a personal loan?", [["Inventory, assessment, quote, signing, payout", "The data are first collected and assessed; only then follow the offer, the signing and the payout."], ["Quote, payout, inventory, assessment and then signing", "Paying out before the inventory and assessment makes the creditworthiness assessment pointless."], ["Assessment, payout, quote, signing, inventory", "Without a prior inventory there is nothing to assess, and payout belongs at the end."], ["Signing, inventory, payout, assessment, quote", "The consumer only signs once they have received a quote after their data have been assessed."]], "1e.1"],
["Credit intermediary Joost is guiding Anouk (28), who is employed and wants to borrow €6,000.00. Joost asks her for complete bank statements for a whole year, including all her expenditure. A recent payslip and an overview of her fixed costs are sufficient for the assessment. Anouk finds the request uncomfortable. Which point for attention mainly arises here?", [["Whether the data are necessary for the purpose (data minimisation)", "The GDPR (AVG) requires only processing data that are necessary for the credit assessment."], ["Whether the customer supplies the statements in colour and on paper", "The form of supply is not a key GDPR question."], ["Whether the intermediary must forward the statements to BKR", "BKR does not receive customers' bank statements."], ["Whether the customer thereby loses their right of withdrawal from the loan", "Requesting documents has no effect on the right of withdrawal."]], "4a.2"],
["How long may a credit provider keep personal data from a credit file under the GDPR (AVG)?", [["No longer than necessary, taking statutory retention obligations into account", "The GDPR prescribes no fixed period; the purpose and statutory obligations, such as those under the Wwft, determine the period."], ["Always for an indefinite period, so that the file remains complete", "Keeping data without limit is contrary to the principle of storage limitation."], ["Exactly one month after the rejection or the conclusion of the credit", "The GDPR has no fixed period of one month."], ["For as long as the customer does not object to the retention", "The retention period depends on the purpose and statutory obligations, not on the absence of an objection."]], "4a.2"],
["Lars (23) has just started his first job and wants to borrow €10,000.00 for a car. The credit provider finds his income insufficiently certain and asks whether someone will stand surety. His father Rob (55) is willing to sign. Rob asks what that means for him. What is correct?", [["If Lars does not pay, the lender can claim the outstanding amount from Rob", "A surety answers for another person's debt; if the borrower does not pay, the lender can hold the surety liable."], ["Rob only has to pay if Lars dies during the term", "Suretyship is not life insurance; the surety also pays in the event of ordinary default."], ["Rob is only liable for the interest and not for the repayment", "A surety is in principle liable for the full debt, up to the agreed amount."], ["The suretyship lapses automatically as soon as Lars gets a permanent contract", "A suretyship does not end automatically because the borrower's position improves."]], "1h.4"],
["What information must an adviser obtain before advising on a consumer credit?", [["Financial position, knowledge and experience, objectives and risk appetite", "Only with a complete client profile can the advice be suitable."], ["Only the monthly instalment the client themselves wishes to pay", "A desired instalment is one wish, not a complete picture of the client."], ["Only the data known about the client at BKR", "BKR data complete the picture, but do not replace the client investigation."], ["Only the purpose for which the client wants to use the loan", "The purpose is important, but ability to pay and circumstances must also be known."]], "2c.1"],
["Jeroen Dekker (35) buys a second-hand car for €14,000.00. He expects to drive it for about five more years. To keep the monthly payment low, he wants a personal loan with a term of ten years. He has a permanent contract and a family with two young children. What is suitable advice?", [["Match the term to the car's useful life, even if the monthly payment is then higher", "A term longer than the useful life means the client is still paying for something they no longer have."], ["Choose the longest term, because a low monthly payment is always better", "A long term increases the total costs and the risk of a residual debt."], ["Advise a revolving credit without a fixed repayment obligation", "Without repayment discipline, the debt remains in place for longer."], ["Advise the client to lease the car and also to borrow", "Double financing of a single spending purpose is not in the client's interest."]], "1h.1"],
["A client takes out a personal loan online without advice, on an execution-only basis. What is correct?", [["That is permitted, but the provider must still assess creditworthiness", "With execution only nobody advises, but the provider's statutory duty to assess remains."], ["That is not permitted, because consumer credit always requires advice", "Consumer credit may also be taken out without advice."], ["That is permitted, and the creditworthiness assessment then lapses for the provider", "The duty to assess does not lapse with execution only."], ["That is only permitted for a loan with a term of more than ten years", "The term does not determine whether execution only is possible."]], "1a.1"],
["What does the general duty of care of a financial services provider mean for consumer credit?", [["Carefully taking the client's legitimate interests into account", "The duty of care is an open standard that can go further than the specific rules, for example where there are signs of financial problems."], ["Always advising the credit with the highest limit", "The highest possible limit is often not in the client's interest."], ["Only providing the statutory information forms", "Providing forms is not enough to satisfy the duty of care."], ["Looking after only the lender's interests", "The duty of care actually concerns the client's interests."]], "1a.1"],
["Wendy Peeters (27) works as a hairdresser and has hardly any savings. She wants to take a long-distance trip with friends and to borrow €4,000.00 for it. Her income is sufficient to pay the monthly instalment. Her washing machine broke down recently and she has not yet replaced it. Which approach fits good advice?", [["Discussing whether borrowing for this is wise and what it means for her buffer", "A good adviser tests not only whether it is possible, but also whether it is in the client's interest."], ["Immediately applying for the highest possible loan so that there is room left over", "Borrowing the maximum does not suit a client without a buffer."], ["Not discussing the spending purpose because that is the client's private affair", "The spending purpose is relevant to suitable advice."], ["Advising paying for the holiday through an overrun on the current account", "An overrun is expensive and unplanned; that is not a suitable alternative."]], "2e.2"],
["What must an adviser record in the client file when advising on consumer credit?", [["Client data, considerations and grounds for the advice", "A good file shows that the advice is suitable and makes it verifiable for the client and the supervisor."], ["Only the client's signature on the provider's quote", "A signature does not show why the advice was suitable."], ["Only the interest rate and the term of the chosen credit product", "The interest rate is one data point; the grounds for the advice would then be missing."], ["Nothing, because advice given orally does not have to be recorded", "Oral advice must also be recorded in order to be able to demonstrate its suitability."]], "2f.1"],
["Ahmed and Sara Benali (both 45) have stable jobs and want to have their garden landscaped for €12,000.00. The gardener's quote is fixed. They are torn between a revolving credit and a personal loan. They want to be sure that the debt is gone when their eldest child goes to study. What is the main argument for the personal loan?", [["Because of the fixed repayment, the debt is gone after the agreed term", "For a one-off, known expense, fixed-term credit with fixed repayment suits better than a limit that can be drawn."], ["A personal loan always has a variable, falling interest rate", "A personal loan usually actually has a fixed interest rate."], ["With a personal loan the client can draw again later", "Drawing again is a feature of revolving credit."], ["A personal loan is not registered with BKR", "A personal loan is also registered with BKR."]], "2e.1"],
["Does the commission ban in the Wft apply to intermediation in consumer credit?", [["No, for consumer credit commission is permitted under conditions", "The commission ban applies to mortgages and complex products, among others; for consumer credit commission is allowed, but the duty of care continues to apply."], ["Yes, the commission ban applies to all forms of credit", "The ban is limited to certain products and does not include consumer credit."], ["Yes, but the commission ban only applies to revolving credit", "The commission ban does not apply to revolving credit either."], ["No, and no further remuneration rules apply to consumer credit either", "Rules do apply, such as the requirement that remuneration must not harm the client's interest."]], "1a.1"],
["Which requirement generally applies to commission that an intermediary receives from a credit provider?", [["Remuneration must not harm careful service to the client", "Commission must not be an incentive to advise a product that is not in the client's interest."], ["The commission must be as high as possible so that the client is better served", "The level of commission is no benefit to the client."], ["The commission must be reported to BKR for each credit taken out", "BKR does not register commissions."], ["The commission must be approved in advance by the AFM", "The AFM does not approve commission arrangements in advance; the remuneration must, however, serve the client's interest."]], "1a.1"],
["Credit intermediary Lisa compares two €15,000.00 personal loans for her client Tom (39). With provider A she receives a higher commission than with provider B. B's loan has a lower APR and is cheaper overall for Tom. Otherwise both loans suit his situation. What is appropriate?", [["Advise the best-fitting loan, even if the commission is lower", "The client's interest comes before one's own interest; a remuneration incentive must not steer the advice."], ["Advise provider A, because the intermediary earns more from it", "Advice based on one's own remuneration is contrary to the duty of care."], ["Let the client choose without mentioning the differences between the two", "The client must receive the information to make a good choice."], ["Take out both loans at the same time so the client can choose which to keep", "Two loans for one purpose are not in the client's interest."]], "2e.2"],
["What must an adviser take into account when refinancing an existing consumer credit?", [["Total costs of old and new, including term and repayment fee", "A lower interest rate can still turn out more expensive because of a longer term or costs."], ["Only the level of the new monthly instalment compared with the old one", "A lower instalment can be the result of a longer term and higher total costs."], ["Only the interest rate of the new loan compared with the current rate", "The interest rate is one factor; term and costs also count."], ["Only whether the client has a BKR registration with an arrears code", "BKR is relevant for the assessment, but does not say whether refinancing is advantageous."]], "3e.2"],
["Mohammed (37) has three revolving credits with different providers, with a total of €14,000.00 drawn. He is losing track and wants to refinance everything into one personal loan. The new provider approves the loan. Mohammed would like to leave the empty limits in place 'for emergencies'. What is an important point for attention?", [["That the old credits are really repaid and the limits are terminated", "If the old limits remain, the client can draw again and the debt increases."], ["That the old credits remain in place as a reserve for unexpected expenses", "Open limits are a risk of extra debt and count in future assessments."], ["That the new loan is given the longest possible term for a low burden", "A long term increases the total costs."], ["That the client does not have to be reassessed when refinancing", "Creditworthiness must also be assessed when refinancing."]], "3e.2"],
["Erik and Joyce Vos (both 50) increase their mortgage by €40,000.00. Of that, they spend €25,000.00 on an extension to their own home. With the remaining €15,000.00 they repay their personal loan for the car. They assume the interest on the entire increase is deductible. What is correct for tax purposes?", [["The interest on the €15,000.00 for the car loan is not deductible", "Only debt for the purchase, improvement or maintenance of the own home can be owner-occupied home debt (eigenwoningschuld); repaying the car loan is a consumption expense."], ["The interest on the entire €40,000.00 is deductible, because it is a mortgage", "The spending determines the deduction, not the form of the loan."], ["The part for the car loan counts in box 1 as owner-occupied home debt", "A consumption expense does not fall under owner-occupied home debt."], ["With NHG (National Mortgage Guarantee), the part for the car loan also becomes owner-occupied home debt", "NHG is a guarantee and does not change the tax nature of a consumption expense."]], "1g.1"],
["Why can refinancing a revolving credit into a personal loan be in the client's interest?", [["Fixed repayment within a fixed term applies, so that the debt decreases", "A revolving credit can remain open for a long time; a personal loan has an end date."], ["The interest rate of a personal loan is always higher than with revolving credit", "A higher interest rate is no benefit to the client."], ["A personal loan, unlike revolving credit, is not registered", "Personal loans are registered too."], ["After refinancing, the client can draw repaid amounts again", "Drawing is precisely not possible with a personal loan."]], "3e.2"],
["A lender transfers a claim arising from a consumer credit to another party. What is the consumer's position?", [["They can also invoke their defences against the new creditor", "The transfer may not worsen the consumer's position."], ["They lose all defences against the new creditor", "The consumer keeps their defences."], ["They must repay the credit in full immediately", "Transfer of the claim does not make the credit callable."], ["They must undergo a new creditworthiness assessment", "When an existing claim is transferred, no new assessment is needed."]], "1f.1"],
["A credit provider uses a credit scoring model with artificial intelligence to assess consumers. How does the AI Act classify this application?", [["As a high-risk AI system", "Creditworthiness assessment of natural persons is listed in the AI Act as a high-risk application."], ["As a prohibited AI practice", "Credit scoring is not prohibited, but is subject to strict requirements."], ["As a minimal-risk application", "Given the impact on access to credit, a higher risk profile applies."], ["As an application that falls outside the regulation", "Credit scoring is expressly named in the regulation."]], "1a.1"],
["Can a consumer with a linked credit turn to the lender if the seller does not deliver the item purchased?", [["Yes, under conditions, after first approaching the seller", "With a linked credit agreement, the consumer can in certain cases seek recourse from the lender."], ["No, the lender and seller are completely separate from one another in all cases", "With a linked credit, the purchase and the credit actually form a commercial unit."], ["Yes, and the lender must then always compensate double the purchase price", "Double compensation does not exist."], ["Only if the AFM gives permission for this in the individual case", "No AFM permission is needed for recourse against the lender."]], "1f.1"],
["An applicant deliberately states a higher income than they earn in order to obtain a loan. How is this to be classified?", [["As fraud, which can lead to refusal or calling in of the credit", "Deliberately incorrect information undermines the creditworthiness assessment and is fraud."], ["As a permissible estimate of future income", "Deliberately stating a higher income is not an estimate but deception."], ["As an error that the intermediary must conceal in the file", "Concealing it makes the intermediary complicit and is contrary to the integrity standards."], ["As an error that the intermediary must conceal in the client file", "BKR does not register income and so does not check it."]], "4a.1"],
["Why does a credit provider ask about the applicant's household situation?", [["Because the standard amount for living expenses depends on the composition of the household", "A family with children has higher fixed costs than a single person, which affects repayment capacity."], ["To determine whether the partner automatically becomes jointly and severally liable", "The household situation does not automatically make a partner liable."], ["Because only married persons and registered partners may take out a loan", "Single persons and cohabitants can also obtain credit."], ["To be able to put the BKR registration in the children's names as well", "Credits are not registered in children's names."]], "2c.1"],
["On what does a consumer pay debit interest with a revolving credit?", [["On the outstanding balance, not on the unused limit", "Interest is calculated on the amount actually drawn and not yet repaid."], ["Always on the full credit limit, even if nothing has been drawn", "No debit interest runs on an undrawn part of the limit; the limit does, however, count in an assessment on a new application."], ["On the amount originally drawn, even after interim repayments", "After repayment the balance falls, and so does the interest; the original amount drawn is not decisive."], ["Only on the amounts drawn in the current month", "Interest runs on the entire outstanding balance, not only on recent drawings."]], "1h.6"],
["How is the monthly instalment of an annuity personal loan made up?", [["Equal instalments with a falling interest portion and rising repayment", "With an annuity the instalment stays the same; as the debt falls, the interest portion becomes smaller and the repayment portion larger."], ["Falling instalments, because a fixed amount of the principal is repaid each month", "A fixed repayment amount per month with falling instalments belongs to linear repayment, not to an annuity."], ["Only interest each month, with the full repayment at the end", "That is an interest-only structure; with an annuity each instalment is also repaid."], ["Instalments that move every half year with the statutory interest rate", "A personal loan usually has a fixed interest rate; the statutory interest rate only determines the maximum cost of credit."]], "1h.3"],
["Nina de Groot (30) wants to finance a new €30,000.00 car. The dealer offers financing with a low monthly payment, but with a final instalment of €12,000.00 at the end of the five-year term. Nina works on a temporary contract. She mainly finds the low monthly payment attractive. What should the adviser mainly look out for?", [["Whether the client can later pay the final instalment or refinance it responsibly", "With a final instalment, a large part of the debt remains outstanding until the end; the client must then be able to pay that amount."], ["Whether the car is still under the manufacturer's warranty at the end of the term", "The warranty says something about the car, not about the risk that the client cannot pay the final instalment."], ["Whether the final instalment may fall outside the statutory maximum cost of credit", "The maximum applies to the cost of credit of the whole credit; a final instalment is repayment and not an exception to it."], ["Whether the client can deduct the interest on the final instalment from their income in box 1", "Interest on car financing is consumption-related and not deductible in box 1."]], "1h.1"],
["What is pawn lending (pandbelening)?", [["Borrowing money with a movable item as security, which is sold in the event of default", "With pawn lending the consumer hands over, for example, a piece of jewellery as security; if they do not repay, the item can be sold."], ["Borrowing money with a mortgage right on one's own home as security", "Security on a home is a mortgage right; that belongs to mortgage credit, not to pawn lending."], ["A loan in which a family member commits in writing as surety for full repayment", "That is suretyship: a person answers for the debt, and no item is given as security."], ["Paying for a purchase in an online shop later or in parts via a payment service", "That is buy now pay later; the consumer does not give an item as security there."]], "1h.4"],
["Mr Smit borrows €25,000.00 from his bank for a new car. The bank establishes a mortgage right on his home for this. How does the Wft classify this credit?", [["As mortgage credit, because it is secured by a mortgage right", "For the Wft the security is decisive: credit to a consumer secured by a mortgage on a home is mortgage credit."], ["As consumer credit, because the money is spent on a car", "The spending purpose does not determine the classification; the mortgage security makes it mortgage credit."], ["As business credit, because a registered property has been given as security", "Mr Smit acts as a private individual; security on registered property does not make a credit a business credit."], ["As hire purchase, because the car only becomes his property after the last instalment", "He buys the car and becomes the owner immediately; there is no hire purchase."]], "1a.1"],
["Does a student loan from DUO fall under the Wft rules for consumer credit?", [["No, the Student Finance Act 2000 (Wet studiefinanciering 2000) applies to it", "DUO provides student finance under its own statutory scheme, not as a credit provider under the Wft."], ["Yes, DUO has an AFM licence as a credit provider for this", "DUO is an implementing organisation of the government and has no AFM licence for granting credit."], ["Yes, but only for the part above the basic grant", "That part is also student finance under the separate statutory scheme, not under the Wft."], ["Only for the part still outstanding after graduation", "The moment of graduation changes nothing about the legal framework of the student debt."]], "1h.2"],
["What characterises a credit card on which the outstanding balance may be repaid in instalments?", [["The balance is not settled all at once and interest is charged on it", "With repayment in instalments a credit arises: the outstanding amount remains and interest is owed on it."], ["The full balance is debited from the account each month without interest", "That describes a card with full monthly settlement; there is then no repayment in instalments."], ["Each payment with the card becomes a separate loan with a fixed term", "With a credit card, one continuing balance arises, not a separate loan per purchase."], ["The card falls outside the concept of credit because payment is made with a card", "The means of payment is not decisive; deferred payment against interest is credit."]], "1h.3"],
["Marieke and Ruud took out a €20,000.00 personal loan together four years ago. They have since divorced. The divorce covenant states that Ruud will pay the loan alone from now on. Marieke wants her own rented home and wants to 'be rid of the loan'. What is correct?", [["She remains jointly and severally liable until the lender releases her", "Both borrowers are liable for the whole; the covenant does not bind the lender, and only the lender can release her."], ["Her liability ends automatically through the agreement in the covenant", "The covenant regulates the relationship between the ex-partners, not their obligations towards the lender."], ["She is from now on only liable for half of the outstanding amount", "Joint and several liability means the lender can claim the whole from each of them."], ["The loan becomes immediately fully callable by operation of law because of the divorce", "A divorce does not automatically make a loan callable; the agreement continues."]], "1d.2"],
["Jan Visser (67) is a widower and dies unexpectedly. He had a personal loan with an outstanding balance of €9,000.00 and no life insurance. His two children are his only heirs. They do not know whether the estate is sufficient to pay the debts. What is correct?", [["The debt falls into the estate; the children can accept beneficially (beneficiair aanvaarden)", "A debt does not lapse on death. Whoever accepts beneficially pays debts only from the estate and not from their own assets."], ["The debt lapses by operation of law on the day of death", "Debts do not cease on death; they form part of the estate."], ["The debt passes to the municipality where Jan lived", "The municipality does not take over deceased persons' debts; they belong to the estate."], ["The lender must write it off, because there is no insurance", "Without insurance the debt simply continues to exist and falls into the estate."]], "1d.2"],
["What is understood by the credit amount in consumer credit?", [["The maximum amount the consumer may draw under the agreement", "The credit amount is the limit or the total amount made available, excluding interest and costs."], ["The amount borrowed plus all interest and other costs over the whole term", "That is the total amount payable by the consumer, not the credit amount."], ["The amount the consumer pays each month in interest and repayment", "That is the instalment; the credit amount is what the consumer may draw."], ["The part of the credit that the consumer has already repaid", "What has been repaid says something about the course of the credit, not about the credit amount."]], "3a.1"],
["Why can the interest rate on a personal loan differ per applicant with the same provider?", [["It can depend on, among other things, the loan amount, the term and the risk", "Providers may differentiate their pricing, as long as the cost of credit stays within the statutory maximum."], ["The AFM sets the permitted interest rate separately for each applicant", "The AFM supervises but does not set an interest rate per consumer; the provider does that."], ["The Wft prescribes a higher interest rate in municipalities with more debt problems", "There is no statutory rule making the interest rate depend on the place of residence."], ["Price differences are prohibited, so a difference always indicates an error", "There is no obligation to charge everyone the same interest rate; only the maximum is limited by law."]], "1e.5"],
["Daan (17) has a part-time job at a supermarket and earns about €400.00 a month. He wants to buy a €900.00 laptop and pay for it in instalments with a loan. His parents know nothing about it. The provider checks his proof of identity and sees his date of birth. What is correct?", [["Without his parents' consent, Daan cannot validly enter into this", "A minor is legally incompetent; a loan like this can be challenged without the parents' consent."], ["That is possible, because loans for electronics fall outside the credit regime", "Financing a laptop is simply credit; the product makes no exception."], ["That is possible, provided the provider properly records his identity and age", "An identity check changes nothing about the fact that as a minor he cannot contract independently."], ["That is possible, because with his part-time job he has a fixed income", "Income does not make a minor legally competent to enter into credit."]], "1b.1"],
["An applicant fills in a net monthly income online but supplies no documents. May the credit provider rely on that statement?", [["No, the income must be checked, for example with a payslip", "The provider must assess creditworthiness on the basis of reliable data and so verify the statement."], ["Yes, the consumer is themselves responsible for the accuracy of their statement", "The consumer's responsibility does not remove the provider's duty to assess carefully."], ["Yes, provided the BKR check shows no arrears or other special entries", "BKR shows credits and arrears, not income; it therefore does not replace the income check."], ["Only if the loan amount is higher than their net annual income", "There is no threshold below which income verification may be omitted."]], "2c.2"],
["Annemiek Peters (62) is a widow and works as an administrative employee. She wants a €20,000.00 personal loan with a term of ten years for a car and a renovation. In five years she will retire, which will reduce her income. At the moment the monthly instalment fits comfortably within her budget. What must the credit provider include in the assessment?", [["The fall in income if she retires during the term", "A foreseeable fall in income within the term is important for whether she can continue to carry the loan."], ["Only her current income, because the future is uncertain anyway", "Foreseeable changes, such as retirement, should actually be taken into account in the assessment."], ["Nothing special; age and pension may not play a role in the assessment", "The issue is not age as such, but the income from which she must pay the instalments."], ["Whether her children are willing to stand surety for the loan", "A surety is no substitute for an assessment of her own ability to pay."]], "3a.2"],
["Frank van Dijk (46) is divorced and pays €600.00 a month in spousal maintenance to his ex-wife. He rents an apartment and works full time as an IT administrator. He wants to borrow €10,000.00 to furnish his new home. He asks whether the maintenance is actually relevant to the application. How does the maintenance count in the assessment?", [["As a fixed charge that reduces the room for a monthly instalment", "He has to pay the maintenance every month; that amount is not available for interest and repayment."], ["It does not, because maintenance is a private arrangement between the ex-partners", "A private arrangement can still be a hard payment obligation that reduces his repayment capacity."], ["As extra income, because he can deduct the maintenance paid for tax purposes", "Any tax benefit does not turn an expense into income; on balance it remains a charge."], ["Only if his ex-partner gives permission to use the data", "He is the applicant; his own charges belong in the assessment, regardless of his ex-partner's permission."]], "1h.5"],
["Two partners jointly apply for a personal loan. What is, as a rule, correct for the creditworthiness assessment?", [["Income, charges and BKR data of both applicants are assessed", "Both partners become borrowers; their joint ability to pay and obligations therefore count."], ["Only the higher income counts; the other income is disregarded", "With a joint application the income of both applicants can be taken into account."], ["Only the first applicant is consulted and registered in the BKR", "Both borrowers are consulted and the credit is registered for both."], ["With a joint application the test against the standard amount for living expenses lapses", "The household's living costs are taken into account then too."]], "1h.5"],
["Does BKR itself take a decision on granting a credit application?", [["No, BKR provides data; the credit provider decides itself", "BKR manages the registration system; the assessment and the decision lie with the provider."], ["Yes, BKR gives a binding positive or negative advice on every application", "BKR gives no binding advice; it only supplies the registered data."], ["Yes, with an arrears code BKR rejects the application on behalf of the provider", "BKR does not reject applications; the provider weighs the registration itself."], ["Only for applications above a statutory loan amount", "There is no amount above which BKR takes over the provider's decision."]], "1b.3"],
["How does an arrears code that is still visible in the BKR usually affect a new credit application?", [["The chance of acceptance falls sharply, because the provider takes the registration into account", "A reported arrear points to an increased risk; providers often reject in that situation."], ["It does not, as long as the consumer has meanwhile repaid the credit concerned", "Even after repayment the registration remains visible for a time and the provider can take it into account."], ["Under the GDPR (AVG) the provider may not include the registration in the assessment", "Consulting and weighing BKR data is precisely part of a careful assessment."], ["There is then a statutory prohibition on granting the consumer any further credit", "There is no absolute statutory prohibition; the provider assesses the risk itself."]], "2d.2"],
["Does a registration in the BKR disappear immediately once the credit has been fully repaid?", [["No, it remains visible for some time after the credit has ended", "After repayment the credit remains registered for a fixed period, so that providers can see the payment history."], ["Yes, the lender must remove the registration on the day of repayment", "A registration is not removed on the repayment date; a retention period applies."], ["Yes, but only if no payment arrear was ever reported during the whole term", "A credit without arrears also remains registered for a period after repayment."], ["No, a registration remains visible for the consumer's entire life", "Registrations are not kept for life; they lapse after a certain period."]], "1b.3"],
["Lotte Meijer (25) works as a junior marketer on a temporary contract that expires in two months. Her employer has not yet said anything about renewal. She wants to borrow €8,000.00 over five years for a car. She lives alone in a studio. What should the provider mainly look out for?", [["Whether the income is sustainable enough to carry the instalments", "An expiring contract makes the income uncertain; the provider must assess whether the instalments remain affordable afterwards too."], ["Nothing, because only the current income on the latest payslip is decisive", "A foreseeable loss of income should actually be taken into account in the assessment."], ["Only whether the applicant has a BKR registration", "BKR says nothing about the sustainability of her income."], ["Whether the employer is willing to stand surety for the loan", "An employer does not as a rule stand surety; the provider must assess the applicant's ability to pay."]], "1d.1"],
["Esra (35) takes out a personal loan with a monthly instalment of €300.00. She is employed on a permanent contract. She is considering payment protection insurance, but does not know exactly what it does. Her adviser explains it. What is correct about payment protection insurance?", [["In the event of involuntary unemployment or incapacity for work it temporarily pays the instalments", "Payment protection insurance takes over the monthly instalments for a limited period on covered events."], ["On any fall in income it repays the whole loan in one go", "Payment protection insurance pays out instalments and does not cover every fall in income."], ["It is legally mandatory for every personal loan above €5,000.00", "Payment protection insurance is not legally mandatory."], ["It also pays out if she herself resigns in order to go travelling", "Resigning of one's own accord is not involuntary unemployment and as a rule falls outside the cover."]], "1h.7"],
["Mehmet Yilmaz (42) pays €250.00 every month on a personal loan that still has three years to run. He has always paid that loan faithfully. He now applies for a second loan of €7,000.00 for a new kitchen. He thinks the first loan does not have to count, because it was already approved earlier. How does the existing loan count in the assessment?", [["With the actual monthly instalment as a fixed charge", "An existing loan weighs on the budget every month; the instalment reduces the room for a new loan."], ["It does not, because the existing loan has already been assessed earlier", "The earlier assessment concerns the old situation; on the new application all existing charges count."], ["Only if a payment arrear has been reported on the existing loan", "A loan paid faithfully is also a fixed charge that counts."], ["With a notional instalment on the original loan amount instead of the actual instalment", "With a fixed-term loan the actual instalment is known and decisive for the charge."]], "1h.5"],
["Why does a credit provider also ask about obligations that are not in the BKR, such as a student debt or private lease?", [["Because charges outside the BKR also limit repayment capacity", "A responsible assessment requires a complete picture of all fixed charges, not only of registered credits."], ["Because the provider must still have those obligations registered with BKR", "The provider only registers its own credit, not the consumer's obligations to others."], ["Because these obligations increase the maximum cost of credit", "The statutory maximum does not depend on the consumer's other obligations."], ["Because the AFM collects that information centrally for statistics", "The data are intended for assessing the application, not for the supervisor's statistics."]], "2c.2"],
["What is the total amount payable by the consumer for a consumer credit?", [["The credit amount plus the total cost of the credit", "This amount shows what the consumer pays in total: the principal plus interest and all other costs."], ["Only the sum of the interest paid over the whole term of the credit", "Interest is one component of the costs; the total amount also includes the credit amount itself."], ["The credit amount without interest and other costs", "That is only the credit amount; the total amount payable is higher because of interest and costs."], ["The monthly instalment multiplied by twelve months", "That is the payments over one year, not the total over the whole term."]], "3a.1"],
["Priya (33) borrows €8,000.00 for a new kitchen. According to the credit agreement she pays 48 monthly instalments of €195.00. There are no other payments. She wants to know what the loan costs her in total. What are the total costs of the credit?", [["€1,360.00", "The total amount payable is 48 x €195.00 = €9,360.00; minus the credit amount of €8,000.00 leaves €1,360.00 in costs."], ["€9,360.00 in total", "That is the total amount payable by Priya, including the borrowed amount itself."], ["€2,340.00", "That is the amount of instalments over one year (12 x €195.00), not the cost of the credit."], ["€800.00", "That is ten per cent of the credit amount; the costs follow from the difference between repayment and loan."]], "3a.1"],
["Mrs Kok has a personal loan and, halfway through the term, wants to know how much interest and repayment she still pays per instalment. What can she ask for?", [["A repayment schedule, free of charge, at any time", "With a credit of fixed duration the consumer has the right to a free repayment schedule on request."], ["Nothing; a repayment schedule is only provided when the credit is concluded", "The right to a repayment schedule applies throughout the term, not only on conclusion."], ["A repayment schedule on payment of administration costs", "The repayment schedule must be provided free of charge."], ["A repayment schedule, but only if she has a payment arrear", "The right does not depend on an arrear; every borrower can ask for it."]], "1a.3"],
["Must a lender inform the consumer before a change in the debit interest rate takes effect?", [["Yes, in advance, with the new instalment amount if it changes", "The consumer must know what an interest rate change means for their payments before it takes effect; different arrangements apply to changes based on a reference rate."], ["No, a variable interest rate may be adjusted without notice to the consumer", "With a variable interest rate too, the lender must inform the consumer of the change."], ["Only if the interest rate rises by more than a statutory percentage", "There is no threshold; the duty to inform applies to every change in the debit interest rate."], ["Only afterwards, in the annual statement the consumer receives in January", "Information afterwards is too late; the consumer must know in advance where they stand."]], "1a.3"],
["What information must a credit intermediary give the consumer in advance about their own position?", [["Whether they work for one or more lenders and what the consumer pays them", "The consumer must be able to judge how independent the intermediary is and what the service costs them."], ["Only their BKR registration number", "Intermediaries have no BKR registration number; the duty to inform concerns their position and remuneration."], ["Their personal income from commission over the past calendar year", "An intermediary does not have to disclose their personal earnings."], ["Nothing; only the lender itself has information obligations towards the consumer", "An intermediary also has its own information obligations towards the consumer."]], "1a.4"],
["Which information must a credit agreement for consumer credit contain, among other things?", [["Credit amount, debit interest rate, APR and right of withdrawal", "These key data must be in the agreement so that the consumer knows their rights and obligations."], ["Only the credit amount and the consumer's signature", "An agreement with only an amount and a signature does not meet the statutory content requirements."], ["A copy of the BKR overview, the payslips and the consumer's bank statements", "Those documents belong in the provider's file, not as mandatory content of the agreement."], ["A statement from the AFM that the credit has been approved in advance", "The AFM does not approve individual credits; that is not part of the agreement."]], "1f.1"],
["In what form must the consumer receive a copy of the credit agreement?", [["On paper or on another durable medium", "A durable medium, such as a PDF that the consumer can keep, ensures they can consult the arrangements later."], ["Only orally, provided the phone call is recorded", "An oral agreement or recording is not sufficient; the consumer must be able to keep the text."], ["Exclusively as a notarial deed signed at the notary's office", "No notarial deed is required for consumer credit."], ["Via a link on a website that stops working after a week", "A temporary web page is not a durable medium, because the consumer cannot consult the text permanently."]], "1a.3"],
["Which life insurance best matches an annuity personal loan?", [["An insurance with a decreasing amount that follows the outstanding debt", "With a fixed-term loan the debt falls; a decreasing sum insured covers the outstanding debt without unnecessary premium."], ["An insurance with an amount that rises further every year", "Rising cover does not fit a debt that is actually falling."], ["A whole-life funeral insurance with a fixed amount", "A funeral insurance covers the funeral costs, not the outstanding debt."], ["An insurance that only pays out on death after the term", "After the term the loan has been repaid; the cover must apply during the term."]], "1h.7"],
["What is the debit interest rate for a consumer credit?", [["The fixed or variable interest on an annual basis on the amount drawn", "The debit interest rate is the interest itself, without the other costs of the credit."], ["The percentage that, besides interest, also includes arrangement fees and other costs of the credit", "That is the annual percentage rate of charge (APR); the debit interest rate contains only the interest."], ["The interest the consumer receives on a positive balance on their account", "Interest on a credit balance is credit interest; the consumer pays debit interest on their debt."], ["The extra interest that applies only as long as there is a payment arrear", "That is default interest on non-compliance, not the ordinary debit interest rate."]], "1h.6"],
["Mrs Visser (55) has received a quote for a €12,000.00 personal loan. It states a debit interest rate of 7.9% and an APR of 8.4%. She thinks there is a mistake in the quote and phones her adviser. He wants to explain it in plain language. How can the difference be explained?", [["The APR also includes other costs and takes the payment rhythm into account", "The APR is an effective annual percentage of all costs; for that reason it is often higher than the nominal debit interest rate."], ["The APR is the interest after the tax benefit of the loan has been taken into account", "There is no tax benefit with consumer credit; the APR is a measure of cost."], ["The debit interest rate already includes the costs of the BKR check", "The debit interest rate contains only interest; costs count in the APR."], ["Owing to a statutory surcharge the APR is always half a percentage point higher", "There is no fixed statutory surcharge; the difference depends on the costs and the payment rhythm."]], "2a.3"],
["What assumption does the APR calculation make for a revolving credit?", [["That the full credit amount is drawn immediately", "Because drawing behaviour is unknown, the APR calculation assumes the limit is drawn in full."], ["That the consumer draws nothing from the limit during the term", "Without drawings there are no interest costs to express as a percentage; that is not how the APR is calculated."], ["That on average half of the limit is drawn", "An average drawing of half is not a prescribed assumption."], ["That the debit interest rises by a fixed percentage every year", "The calculation actually assumes the interest rate to be constant."]], "1h.6"],
["A lender grants a loan only if the consumer also takes out a life insurance. How does the premium count in the APR?", [["The premium counts in the total costs, because the insurance is mandatory", "Costs of a mandatory ancillary service in order to obtain the credit form part of the total costs and so of the APR."], ["It does not, insurance premiums never belong to the costs of the credit", "A mandatory insurance is precisely a cost item that is counted in the total costs."], ["Only if the insurance is with the same company as the loan", "What is decisive is whether the insurance is mandatory, not with which party it is taken out."], ["Only the commission the intermediary receives on the premium counts in the APR", "Not just a commission portion, but the premium of the mandatory insurance belongs to the costs."]], "1h.6"],
["Does the purchase price of a television bought with a linked credit count in the total cost of the credit?", [["No, that price is also owed in the case of cash payment", "Only costs connected with the credit count; the price of the item does not belong to them."], ["Yes, the APR is calculated on the total purchase price including interest", "The APR expresses the cost of the credit; the purchase price itself is not a cost item of the credit."], ["Yes, but only if the purchase is structured as hire purchase", "With hire purchase too, the price of the item is not a credit cost; only the cost of credit is."], ["Only the part of the price that is above the manufacturer's recommended retail price", "A recommended retail price plays no role in determining the credit costs."]], "1h.6"],
["A consumer pays an instalment of their personal loan two months late. On what may the lender charge default interest?", [["On the overdue amount, for the duration of the arrear", "Default interest is compensation for late payment and is calculated on the amount paid late."], ["On the original credit amount, from the start of the loan", "Ordinary interest has already been paid on the original amount; the delay concerns only the overdue instalment."], ["On the entire outstanding balance, even to the extent that it is not callable", "For the part that is not yet callable, the consumer is not late."], ["On all future instalments up to the end of the term", "Future instalments are not yet owed and so have not been paid late."]], "1i.3"],
["A lender requires the consumer to open a current account with it for the credit. Do the costs of that account count in the APR?", [["Yes, if the account is mandatory to obtain the credit", "Costs of an account that is mandatory for the credit belong to the total cost of the credit."], ["No, current accounts fall under another European directive", "That current accounts have their own rules does not change that mandatory account costs belong to the credit costs."], ["Only if the account is with a different bank than the lender", "What matters is whether the account is mandatory, not at which bank it is held."], ["No, only the costs of a linked credit card count", "There is no limitation to credit cards; mandatory account costs count as well."]], "1h.6"],
["Bas and Eline (both 32) want to borrow €15,000.00 for a renovation. Loan A has an APR of 7.5% and a term of five years. Loan B has the same APR, but a term of eight years and consequently a lower monthly payment. They lean towards B, because it 'feels cheaper'. What is correct?", [["Loan B costs more interest in total because of the longer term", "With an equal APR the debt under B runs longer and interest is therefore paid for longer, even though the monthly payment is lower."], ["Both loans cost the same in total, because the APR is the same", "The APR is an annual percentage; the total also depends on the term."], ["Loan B is cheaper, because the monthly payment per instalment is lower", "A lower monthly payment through a longer term actually means more total interest."], ["Loan A costs more in total, because a higher amount is repaid each month", "Repaying faster reduces the interest burden; A therefore costs less in total."]], "1h.6"],
["Does a fee that the consumer must pay directly to a credit intermediary count in the total cost of the credit?", [["Yes, if the lender knows of that fee, it counts", "Costs the consumer must pay in connection with the credit, such as an intermediation fee, count in the APR."], ["No, intermediation costs are always separate from the credit", "A mandatory fee for the intermediation is a cost item connected with the credit."], ["Only if the intermediary and the lender are the same company", "What matters are the costs to the consumer, not whether the intermediary and the lender coincide."], ["Only the part of the fee that the intermediary passes on to the AFM", "Intermediaries do not pass on any part of their fee to the AFM."]], "1h.6"],
["Must a consumer give a reason if they withdraw from a credit agreement within the withdrawal period?", [["No, withdrawal is possible without giving reasons", "The right of withdrawal gives the consumer time to reconsider; they do not have to explain why they are giving up the credit."], ["Yes, only a pressing reason such as dismissal or illness counts", "A pressing reason is not required; the right is unconditional within the period."], ["Yes, the lender must first approve the stated reason in writing", "The lender does not have to agree; the withdrawal takes effect through the consumer's notice."], ["Only if the borrowed money has already been paid into their account", "A reason is not needed then either; payout only affects the repayment."]], "1f.1"],
["Sven (36) took out a personal loan online two weeks ago and received all the information at that time. On the last day of the withdrawal period he sends the lender an e-mail in the evening saying he is withdrawing from the loan. An employee of the lender reads the e-mail only two days later. The lender argues the withdrawal is too late. Is the withdrawal in time?", [["Yes, sending before the end of the period is sufficient", "For timeliness what counts is that the notice was sent within the period, not when the lender reads it."], ["No, the lender must have read the withdrawal within the period", "The moment the lender reads it is not decisive for timeliness."], ["No, withdrawal is only possible by registered letter", "No registered letter is needed; a notice on a durable medium such as an e-mail is sufficient."], ["Only if the lender confirmed receipt within the period", "An acknowledgement of receipt is not a condition for a valid withdrawal."]], "1f.1"],
["Mr Jacobs (60) took out a €10,000.00 personal loan through a credit intermediary. After nine days he withdraws from the loan because his son can lend him the money. He repays the borrowed amount immediately. The lender also wants to charge the intermediary's commission and an administration fee. Which costs may the lender charge in addition to the accrued interest?", [["Only non-refundable costs it has paid to the government", "Withdrawal must in principle be free of charge; only such government costs may be passed on."], ["A fixed withdrawal fine of one per cent of the credit amount", "A fine would undermine the right of withdrawal and is not permitted."], ["The interest it would have received over the rest of the original term", "Only interest for the period from drawdown to repayment is owed."], ["The commission it has paid to the intermediary", "Commission to an intermediary is a cost item of the lender and may not be passed on on withdrawal."]], "1f.1"],
["Does the right of withdrawal also apply to a revolving credit?", [["Yes, for credits of both fixed and indefinite duration", "With a revolving credit too, the consumer can withdraw within the period without giving reasons."], ["No, only for a personal loan with a fixed term", "The right of withdrawal is not limited to loans with a fixed term."], ["Only if the consumer has not yet drawn anything from the limit", "They can withdraw after a drawing too; they then repay the amount drawn with interest."], ["Only if the revolving credit is linked to a specific purchase", "A link to a purchase is not a condition for the right of withdrawal."]], "1f.1"],
["Pim (41) takes out a personal loan and, through the lender, also takes payment protection insurance, on the basis of an arrangement between the lender and the insurer. A week later he withdraws from the loan because his bonus was paid out earlier than expected. He has not separately cancelled the insurance. He wonders whether he is still tied to it. What applies to the payment protection insurance?", [["In principle he is also no longer bound by that ancillary service", "An ancillary service concluded through the lender on the basis of an arrangement with it lapses in principle together with the withdrawal."], ["It continues until the end of the original term of the loan", "An insurance that belongs to the credit does not continue to exist if the credit lapses retroactively."], ["He must cancel it separately and pay a fine for that", "The law actually protects the consumer against costs on withdrawal; a fine does not fit that."], ["The premium is converted into a new loan with the same term", "No new loan arises; the ancillary service lapses."]], "1f.1"],
["Marco (48) has an annuity personal loan with a remaining debt of €12,000.00 and four years left to run. He makes an extra repayment of €4,000.00. His lender offers him the choice between a lower monthly amount or the same monthly amount. Marco wants to know what that means for him. What is correct?", [["With the same monthly amount the term becomes shorter; otherwise the monthly amount falls", "After an extra repayment the debt is lower; it can be repaid faster, or with lower instalments in the same time."], ["An extra repayment changes nothing about the monthly amount or the term", "A lower debt actually has consequences for the term or the instalment amount."], ["With the same monthly amount the term actually becomes longer", "With the same instalment on a lower debt the loan is repaid sooner, not later."], ["After the extra repayment the interest on the remainder of the loan rises", "An extra repayment is no reason for a higher interest rate on the remainder."]], "1i.4"],
["Can the right of withdrawal for consumer credit be excluded in the agreement?", [["No, it is a mandatory right of the consumer", "The statutory protection of the consumer in credit cannot be departed from to the consumer's disadvantage."], ["Yes, if the consumer agrees to it in writing in advance", "The consumer's consent does not make a departure to their disadvantage valid."], ["Yes, for loans with an interest rate below the statutory interest rate", "The level of the interest rate has no effect on the right of withdrawal."], ["Yes, if the loan was paid out immediately after signing", "Payout does not remove the right of withdrawal; the consumer then repays."]], "1f.1"],
["Mr Bos wants to repay his fixed-rate personal loan in full two years before the end of the term. What is the maximum fee the lender may charge?", [["1% of the amount repaid early", "With a remaining term of more than one year, the fee is capped at 1% of the amount repaid."], ["0.5% of the amount repaid early", "That maximum applies if the remaining term is one year or less."], ["Three months' interest on the amount repaid", "A fee expressed in months of interest is not a statutory measure for consumer credit."], ["The full interest over the remaining two years", "That would discourage early repayment; the fee is bound by law to a low percentage."]], "3e.1"],
["Carla (54) has a fixed-rate personal loan. Eight months before the end of the term she receives a bonus. With it she repays the remaining €6,000.00 in one go. The interest she would still have paid up to the end of the term is more than €100.00. What is the maximum fee the lender may charge?", [["€30.00", "With a remaining term of one year or less, the fee is capped at 0.5% of the amount repaid: 0.5% of €6,000.00."], ["€60.00", "That is 1%; that maximum only applies with a remaining term of more than one year."], ["Nothing, because no fee may be charged in the last year", "In the last year too, a limited fee may be charged with a fixed interest rate."], ["€120.00", "That is 2% and exceeds any statutory maximum for the fee on consumer credit."]], "3e.1"],
["Which upper limit applies, besides the maximum percentage, to the fee for early repayment of consumer credit?", [["Not more than the interest up to the end of the term", "The consumer never has to pay more than the interest they would have paid had they not repaid early."], ["The fee may never be higher than one monthly instalment", "A monthly instalment is not a statutory upper limit for the early repayment fee."], ["The fee may not be higher than the statutory interest for one year", "The statutory interest rate plays no role in the early repayment fee."], ["Besides the maximum percentage, no other limit applies", "The fee is also limited by the interest the consumer would still have paid."]], "3e.1"],
["A lender wants to terminate a customer's revolving credit of indefinite duration; the agreement allows this. How must it do so?", [["With a notice period of at least two months, on a durable medium", "This gives the consumer time to find another solution; the notice must be on paper or a durable medium."], ["At any time, without a notice period and without any prior notice to the customer", "Termination by the lender is subject to a minimum notice period and a notification."], ["Only with the prior permission of the AFM", "The AFM does not have to agree to the termination of an individual credit."], ["Only after the subdistrict court judge (kantonrechter) has approved the termination", "No intervention by the court is needed for a termination in accordance with the agreement."]], "1f.1"],
["Ingrid (50) has a fixed-rate personal loan with a remaining term of three years. She sells her caravan and repays the remaining €12,000.00 in one go. According to the agreement, the lender charges the statutory maximum fee. The interest over the remaining term would be well over €1,000.00. What is the maximum fee the lender may charge?", [["€120.00", "With a remaining term of more than one year, the fee is capped at 1% of the amount repaid: 1% of €12,000.00."], ["€60.00", "That is 0.5%; that maximum applies if the remaining term is one year or less."], ["€1,000.00", "The interest over the remaining term is only an upper limit; the maximum of 1% is lower here."], ["€240.00", "That is 2% and exceeds the statutory maximum for the fee."]], "3e.1"],
["A consumer does not pay their loan and does not respond to reminders. The lender wants to attach their wages. What is needed for that in principle?", [["An enforceable title (executoriale titel), such as a judgment, and a bailiff", "Wage attachment requires an enforceable title and is levied by a court bailiff, observing the protected income."], ["Only a registration of the arrear in the BKR", "A BKR registration gives no right to levy attachment."], ["Permission from the AFM and a registered letter", "The AFM is not involved in the attachment of a consumer's wages."], ["A written statement from the employer", "The employer does not decide on attachment; an enforceable title is needed for that."]], "1i.5"],
["Adviser Mirjam receives from her client Kevin (31) a payslip with an application for a €15,000.00 loan. The font of the net amount differs from the rest of the payslip. The amount also does not match the credit on his bank statement. Kevin presses for a quick application. What is appropriate for Mirjam?", [["Not submit the application in this form and handle the signal in accordance with the fraud procedure", "A suspected forged payslip is a fraud signal; the adviser investigates it and acts in accordance with the internal procedure."], ["Submit the payslip anyway, because the lender checks it itself", "The adviser must be alert to the authenticity of documents themselves and may not forward a suspicious document."], ["Ask Kevin to neatly correct the net amount on the payslip", "Having a document altered does not resolve the fraud signal and makes it worse."], ["Fill in the amount from the bank statement and do nothing further", "That leaves the fraud signal unaddressed and there is no reliable substantiation."]], "4a.1"],
["Does the statutory maximum for the cost of credit also apply to hire purchase and purchase by instalments?", [["Yes, the cost of credit is also capped for those forms of credit", "Hire purchase and purchase by instalments are forms of consumer credit; the charge for them falls under the maximum."], ["No, the maximum only applies to loans of money such as a personal loan", "The maximum is not limited to loans of money; credit on the purchase of an item falls under it too."], ["No, because with hire purchase rent, not interest, is paid", "What the instalments are called is not decisive; the charge for the credit is capped."], ["Only if the seller also has an AFM licence", "Whether the maximum applies does not depend on the seller's licence."]], "1h.6"],
["The statutory interest rate falls, as a result of which the variable interest rate on an existing revolving credit exceeds the new maximum. What must the lender do?", [["Reduce the interest rate to within the new maximum", "With a variable interest rate, the cost of credit must at all times stay within the applicable maximum."], ["Nothing, because the maximum only applied on the day of conclusion", "For a variable interest rate the maximum applies continuously, not only at the outset."], ["Call in the credit immediately because it is no longer permitted", "Calling in is neither necessary nor permitted for this reason; the interest rate must be adjusted."], ["Let the consumer choose between a higher interest rate or termination", "The consumer cannot validly agree to a charge above the statutory maximum."]], "1i.1"],
["Does a bank holding a banking licence additionally need a separate AFM licence to offer consumer credit?", [["No, the banking licence suffices; the conduct rules do apply", "Banks are exempt from the separate licence requirement for credit providers; the AFM does supervise their conduct towards consumers."], ["Yes, every credit provider must always also hold an AFM licence", "An exception to the separate licence requirement for credit providers applies to banks."], ["No, and the conduct rules for credit do not apply to banks either", "The conduct rules actually also apply to banks that offer credit."], ["Yes, and in addition a recognition by BKR", "BKR is a credit registration foundation and grants no licences."]], "1a.1"],
["Adviser Peter specialises in consumer credit and has no diploma for mortgage credit. His client Ellen (58) wants to repay her personal loan. She asks him whether she would do better to increase her mortgage for this. Ellen wants an answer straight away. What is appropriate?", [["Refer Ellen to an adviser with expertise in mortgage credit", "An adviser knows the limits of their professional competence and refers on when a question falls outside it."], ["Give some general mortgage advice himself, because Ellen is asking for it now", "Without the required professional competence he may not advise on mortgage credit."], ["Ignore the question and discuss only the personal loan", "A relevant question from the client would then remain unanswered; referring on is better."], ["Recommend that Ellen increase her mortgage online herself", "In doing so he shifts his responsibility away without Ellen being properly advised."]], "4a.3"],
["What is the status of the VFN Code of Conduct?", [["Self-regulation that binds the members and fleshes out the statutory standards", "The code of conduct was drawn up by the industry itself and gives concrete shape to responsible lending."], ["An act adopted by Parliament", "The code of conduct is not an act but an agreement within the industry."], ["Non-binding advice from the industry that members need not follow", "Members are bound by the code of conduct; it is not non-binding advice."], ["A BKR regulation on the registration of credits", "The code of conduct is the VFN's and concerns responsible lending, not BKR registration."]], "1a.1"],
["Thomas Bakker (38) is self-employed and has his own handyman business. He wants to borrow €10,000.00 to buy a van. He uses the van only for his business. Privately he drives his wife's car. Does this credit fall under the rules for consumer credit?", [["No, he is acting in the exercise of his business", "Credit for business purposes falls outside the consumer credit regime, even if the entrepreneur is a natural person."], ["Yes, a self-employed person is always a consumer as a natural person", "What matters is whether someone acts outside their profession or business, not just whether they are a natural person."], ["Yes, because the amount stays below the limit for business credit", "There is no amount limit that turns business credit into consumer credit."], ["Only if he takes out the loan through a credit intermediary", "Whether there is an intermediary changes nothing about the business nature of the credit."]], "1a.1"],
["What does the Wft mainly regulate for consumer credit, compared with Book 7 of the Dutch Civil Code (BW)?", [["Supervision, such as the licence requirement and the conduct rules", "The Wft is supervisory legislation; the civil-law relationship between the parties is mainly in the BW."], ["The civil-law rules on withdrawal and early repayment of the credit", "Those rules are largely in Book 7 BW, not in the Wft."], ["The criminalisation of usury and the penalty for it", "Criminal provisions are in criminal law; the Wft is not intended for that."], ["The tax treatment of interest on consumer credit", "The tax treatment is in tax legislation, not in the Wft."]], "1a.1"],
["An employee of a credit provider is asked by their neighbour whether the neighbour's new girlfriend has 'BKR problems'. What is correct?", [["Give no information; data may only be used for a legitimate purpose", "BKR data may only be consulted and used for a credit application or credit management, not for private questions."], ["Only say whether there is an arrears code, without mentioning amounts", "Sharing even limited information is misuse of client data."], ["Give the information if the neighbour promises to keep it secret", "A promise of secrecy does not make an unlawful consultation lawful."], ["Look up the data, but only pass it on orally", "Consulting without a legitimate purpose is already not permitted."]], "4a.2"],
["What is the difference between a credit provider and a credit intermediary?", [["The provider grants the credit, the intermediary brings the parties together", "The provider is the counterparty in the credit agreement; the intermediary carries out activities to bring that agreement about."], ["The intermediary bears the credit risk if the consumer does not pay", "The credit risk lies with the provider, who supplies the money."], ["There is no difference; both terms mean the same", "They are different roles, each with its own obligations under the Wft."], ["The provider advises the client, and the intermediary approves the credit application", "Approving the application is for the provider, not the intermediary."]], "1a.4"],
["Adviser Sanne has discussed a €9,000.00 personal loan with a term of 48 months with her client Joris (40). The lender's quote comes in and Joris wants to sign it digitally straight away. Sanne sees that the quote states a term of 72 months. A payment protection insurance, which Joris did not want, is also included. What is appropriate?", [["Let Joris wait and have the quote corrected first", "An adviser checks the quote for errors; Joris should sign for what was agreed."], ["Let him sign and sort out the errors with the lender after payout", "After signing, Joris is bound by the deviating terms; that is not careful."], ["Let him sign, because Joris can withdraw from the loan afterwards anyway", "The right of withdrawal is not a solution for a quote that is wrong."], ["Change the term in the document herself and let him sign", "An adviser may not change a lender's quote herself."]], "2a.5"],
["Up to what credit amount does a consumer credit in principle fall under CCD II?", [["Up to €100,000.00", "CCD II raises the upper limit of the scope to €100,000.00."], ["Up to €75,000.00", "That was the upper limit under the old directive (CCD I)."], ["Up to €50,000.00", "A limit of €50,000.00 does not occur in the directive."], ["Under CCD II there is no longer an upper limit", "CCD II has dropped the lower threshold, but does have an upper limit."]], "1a.2"],
["Which credits in principle fall outside CCD II?", [["Credits secured by a mortgage right on a home", "Such credits fall under the Mortgage Credit Directive (MCD), not under CCD II."], ["Buy now pay later credits from an external provider", "CCD II actually brings BNPL under the credit regime."], ["Credits with a credit amount under €200.00", "CCD II removes the old lower threshold, so that small credits also fall under it."], ["Revolving credits with a variable interest rate", "Revolving credit is a classic form of consumer credit under the directive."]], "1a.2"],
["Which advertising message for credit is prohibited under CCD II?", [["Advertising that suggests credit improves the financial situation", "CCD II prohibits advertising that presents borrowing as a solution to financial problems."], ["Advertising that states the annual percentage rate of charge", "Stating the APR is actually a mandatory part of advertising that mentions costs."], ["Advertising with a representative example of a loan and the associated APR", "A representative example is actually required in advertising with interest rate figures."], ["Advertising with a warning about the costs of borrowing", "A warning about the costs of credit fits the protection and is not prohibited."]], "1a.2"],
["An adviser enters the client's gross monthly income into a borrowing capacity calculation model where net income is requested. What is the consequence?", [["The borrowing capacity comes out too high, with a risk of over-indebtedness", "Gross income is higher than what the client actually receives; the model then calculates with too much room."], ["The borrowing capacity comes out too low, so that the client can borrow less", "Gross is higher than net; the result therefore comes out too high."], ["There is no consequence, because the model converts gross to net itself", "If the model asks for net, it calculates with what was entered."], ["Only the term is calculated differently, not the amount", "The income input actually affects the maximum amount."]], "2b.1"],
["Jesse (34) has applied through an intermediary for a €12,000.00 personal loan. Two days before signing, he hears that his temporary contract will not be renewed. The application has already been approved, but the loan has not yet been paid out. He asks the intermediary whether he must report this. What is correct?", [["He must report it, so that the lender can reassess", "A material change in income before the loan is granted is important for the assessment and must be reported."], ["He does not have to report anything, because approval has already been given", "The approval is based on data that are no longer correct."], ["He had better sign first and only report it afterwards", "Deliberately withholding a change until after signing is misleading."], ["Only if he does not find a new job within a month", "The change is now known and must be reported now."]], "2e.3"],
["Ellen Koopman (44) has applied for a €15,000.00 loan together with her adviser. The lender rejects the application because her fixed charges are too high for her income. Ellen is disappointed and thinks the adviser 'should sort it out'. The adviser prepares the conversation with her. What best fits discussing the rejection?", [["Explain the reason clearly and discuss what options remain", "On a rejection, the adviser explains which factors were decisive and what the client can realistically do."], ["Submit the application elsewhere with a higher stated income", "Deliberately giving incorrect information is fraud."], ["Just let her know briefly by e-mail that the application has been rejected", "Bad news calls for an explanation, so that the client understands why and what now."], ["Blame the rejection on a system error to spare her", "That is misleading and takes away the client's chance to improve her situation."]], "3d.1"],
["Adviser Ruben advises Jolanda (52) to take a €8,000.00 personal loan with a term of five years. Jolanda nevertheless chooses a €8,000.00 revolving credit. Ruben has explained the risks of that to her. At her request the revolving credit is applied for. What must Ruben record in the file?", [["His advice, her deviating choice and the risks discussed", "A good file shows what was advised, what the client chose and which risks were discussed."], ["Only the product that was ultimately applied for", "Without the advice and the considerations, the file cannot be reconstructed."], ["Nothing, because Jolanda chose the credit herself", "Even when the client makes a deviating choice, the advice process must be recorded."], ["Only her signature under the credit application", "A signature does not show which advice was given and why."]], "2f.1"],
["Two ex-partners have a revolving credit together. One of them asks the lender to be released from the agreement. What does the lender as a rule do before agreeing to this?", [["Assess whether the remaining partner can carry the credit alone", "Release from joint and several liability is a change in which the lender tests the ability to pay of the remaining borrower."], ["Agree immediately, because a divorce gives a statutory right to release", "There is no statutory right to release from liability because of a divorce."], ["Automatically split the credit into two separate credits", "A credit is not split automatically; that requires a new agreement and assessment."], ["Forward the request to BKR, which decides on the release", "BKR registers data but does not decide on contract changes."]], "1i.1"],
["What does CCD II provide about tying in consumer credit?", [["Tying is in principle prohibited, with a few exceptions", "A credit may in principle not be offered solely together with another product, so that the consumer can choose freely."], ["Tying is always permitted if the APR of the package is stated", "Stating the APR does not make a tying that is in principle prohibited permissible."], ["Tying is mandatory to give the consumer extra protection", "An obligation to tie would limit the consumer's freedom of choice."], ["Tying is only prohibited for loans above €50,000.00", "The prohibition does not depend on a credit amount."]], "1a.2"],
["What is a debt restructuring loan (saneringskrediet)?", [["A loan from, for example, a municipal credit bank to buy off creditors", "The creditors receive a percentage immediately and write off the rest; the debtor repays the loan to the credit bank."], ["A revolving credit for making new purchases during the debt assistance process", "A debt restructuring loan is actually intended to settle existing debts, not to make new purchases."], ["A debt discharge pronounced by the court in the Wsnp", "The clean slate in the Wsnp is not a loan; a debt restructuring loan belongs to the amicable arrangement."], ["An interest-free loan from the Dutch Tax Administration for tax debts", "The Dutch Tax Administration does not provide debt restructuring loans to debtors."]], "1f.2"],
["What is a compulsory settlement (dwangakkoord)?", [["The court obliges a refusing creditor to cooperate in an arrangement", "If one creditor blocks a reasonable settlement, the court can compel it to cooperate."], ["A creditor forces the debtor to sell their home", "That is enforcement by a creditor, not a compulsory settlement."], ["An agreement between a lender and BKR on the removal of a registration", "BKR and lenders do not conclude compulsory settlements; the concept belongs to debt arrangements."], ["A mandatory payment arrangement imposed by the Dutch Tax Administration", "A compulsory settlement comes about through the court and concerns all creditors in an arrangement."]], "1f.2"],
["What does protective administration (beschermingsbewind) entail?", [["A court-appointed administrator manages the finances", "Administration protects people who cannot manage their finances themselves; the administrator manages income and assets."], ["A voluntary budget course offered by the municipality to residents with debts", "A course is a form of prevention; protective administration is a measure ordered by the court."], ["The temporary freezing of all debts by the bank", "A bank cannot freeze debts in that way; administration concerns the management of assets."], ["A measure under which BKR removes all registrations", "Protective administration has no effect on existing BKR registrations."]], "1c.1"],
["A creditor wants to charge a consumer extrajudicial collection costs. What must they first do under the Debt Collection Costs Act (Wet incassokosten)?", [["Send a reminder with a payment period of at least fourteen days", "The consumer must first get a last chance to pay without collection costs."], ["Immediately engage a court bailiff to collect the claim with costs", "Without a prior reminder with a time limit, no collection costs may be charged."], ["First have a BKR registration made", "A BKR registration is not a condition for collection costs and does not apply to every debt."], ["Await a court judgment awarding the collection costs", "Extrajudicial costs are precisely incurred before any proceedings."]], "1i.2"],
["What is the purpose of a cooling-off period that the court can order during a debt assistance process?", [["Temporarily holding back creditors to allow a debt arrangement", "During the cooling-off period, creditors cannot temporarily levy attachment or take certain measures."], ["Definitively writing off the consumer's debts", "A cooling-off period is temporary and writes off no debts."], ["Temporarily raising the interest on existing debts", "An interest rate increase does not fit the aim of calm in the process."], ["Temporarily enabling the consumer to take out new credit to make ends meet", "New credit would worsen the debt position and does not fit the process."]], "1f.2"],
["What is budget management (budgetbeheer)?", [["Income goes into a management account, from which fixed costs are paid", "Budget management ensures the most important charges are paid before the consumer has the remainder at their disposal."], ["A loan from the municipality with which all creditors are paid at once", "That is a debt restructuring loan, not budget management."], ["A statutory debt restructuring with a clean slate at the end", "That is the Wsnp, a route through the court."], ["A calculation model with which borrowing capacity is calculated", "That is a tool for credit assessment; budget management is a practical service for the consumer."]], "1f.2"],
["Nadia (39) is a single mother of two children and has been in an amicable debt assistance process via her municipality for six months. Her washing machine and fridge break down. She applies to an online provider for a €1,500.00 loan for new appliances. She has not informed her debt counsellor about it. What is correct?", [["New credit runs counter to the process and can jeopardise the arrangement", "In a debt arrangement the debtor may as a rule not incur new debts; new credit undermines the agreement with creditors."], ["That is mandatory, so that creditors in the process can be paid faster", "New debts do not solve the problem and are not part of an amicable arrangement."], ["That is fine, because the amicable process is voluntary", "A voluntary arrangement also contains agreements that exclude new debts."], ["The municipality must in that case provide the loan itself", "The municipality has no duty to provide extra credit during the process."]], "1c.2"],
["What is understood in debt assistance by problematic debts?", [["Debts that the consumer, on reasonable expectation, cannot continue to pay", "This concerns a situation in which the consumer can no longer repay their debts or is not expected to be able to."], ["All debts above a statutorily set amount", "A debt becomes problematic through being unaffordable, not through a fixed amount."], ["Only debts to the Dutch Tax Administration, the municipality and other government bodies", "Debts to lenders and other private parties can also be problematic."], ["Every debt that is registered with BKR", "A BKR registration does not mean the debts are unaffordable."]], "1f.2"],
["Kim (34) and her boyfriend want to finance a new €5,000.00 kitchen. Their adviser proposes 'for convenience' a revolving credit with a limit of €15,000.00. According to him they can then also do the bathroom later. Kim and her boyfriend have no plans for that yet. What is the objection to this advice?", [["The limit is far above the need and can lead to unnecessary debt", "A limit that is too high tempts extra drawings and counts in later applications, without the client needing it."], ["Revolving credits above €10,000.00 are prohibited by law", "No such statutory prohibition exists; the objection lies in suitability for this client."], ["The only objection is that the adviser's commission turns out lower", "The commission is not the point; it is about the client's interest."], ["There is no objection; a higher limit is always more favourable for the client", "A higher limit than needed actually brings risks for the client."]], "3b.1"],
["Henk (61) has €20,000.00 in his savings account. He wants to buy a €6,000.00 second-hand car. He applies for a personal loan because he 'would rather not touch' his savings. He has no other large expenses planned. What belongs to good advice?", [["Discussing whether paying from savings is more advantageous, while keeping a buffer", "Borrowing usually costs more than savings earn; a good adviser weighs that choice with an eye to a buffer."], ["Always advising borrowing, because savings may not be touched", "There is no rule prohibiting the use of savings; it may actually be more advantageous."], ["Refusing the loan, because someone with savings may not borrow", "A client with assets may borrow; the question is whether it is wise."], ["Advising investing the savings to earn back the interest on the loan", "That brings extra risk and is not a careful consideration for this client."]], "2d.1"],
["What is the difference between advising and informing in consumer credit?", [["With advice a personal recommendation follows, based on the client's situation", "Informing is about factual explanation; advice is a recommendation tailored to the client."], ["With informing the client may not ask the intermediary questions about the product", "With provision of information the client can also ask questions; the difference lies in the recommendation."], ["Advice is always written, information always oral", "The form is not decisive for the distinction between advice and information."], ["There is no difference; both are a recommendation for a product", "With informing no personal recommendation is made."]], "1a.1"],
["Mrs Nowak (45) has lived in the Netherlands for three years and works in a distribution centre. She wants to take out a €4,000.00 personal loan through an intermediary. She speaks and reads Dutch poorly. The intermediary notices that she does not properly understand questions about the term and the interest rate. What fits the duty of care?", [["Check that the client truly understands the information and obligations", "The duty of care requires the service provider to take the client into account, so that they understand what they are entering into."], ["Nothing extra; all the information is in Dutch on the intermediary's website", "Providing information is not enough if it is clear the client does not understand it."], ["Refuse the client because they do not master the Dutch language well", "Refusing solely because of the language is not necessary; the adviser must ensure understanding."], ["Have the client sign for receipt; understanding is their own risk", "A signature for receipt does not remove the service provider's duty of care."]], "2a.2"],
["What can be the consequence if an adviser breaches their duty of care in consumer credit?", [["They may be liable for the loss the client suffers", "A breach of the duty of care can lead to compensation, for example via Kifid or the court."], ["The client never has to repay the borrowed amount", "A breach of the duty of care as a rule leaves the client's repayment obligation in place."], ["The credit is automatically converted into an interest-free loan", "There is no automatic conversion; the consequences are assessed case by case."], ["There are no consequences; the duty of care is a guideline without sanctions", "The duty of care is a legal standard with civil-law and supervisory consequences."]], "1a.1"],
["Why must an adviser know the client's purpose for borrowing?", [["In order to be able to tailor form, amount and term to that purpose", "A car, a renovation or a holiday each call for a different weighing of form and term."], ["Because the borrowing purpose is registered with BKR", "BKR registers the type of credit and the amount, not the spending purpose."], ["Because the borrowing purpose determines the level of the maximum cost of credit", "The maximum depends on the statutory interest rate, not on the purpose."], ["Because borrowing without a concrete purpose is prohibited by law", "There is no statutory prohibition on borrowing without a concrete purpose."]], "2c.1"],
["Robin (29) works part-time in hospitality and is about €150.00 short every month for his groceries. He has a revolving credit and wants from now on always to draw that shortfall from the credit. He can just about pay the monthly instalment. He asks his adviser whether that is a good idea. What is the main risk?", [["The debt grows every month, while the shortfall remains", "The shortfall remains and interest makes the situation worse every month; that points to a budget problem."], ["There is no risk as long as he pays the monthly instalments", "Even with timely instalments the debt grows if he draws again every month."], ["The only risk is that the interest on the revolving credit is variable", "The variable interest rate is not the core problem; that is the structural shortfall."], ["Groceries may not legally be paid for with credit", "There is no legal prohibition; what matters is the responsibility of the advice."]], "1c.2"],
["Gijs (26) took out a €5,000.00 personal loan for a motorbike ten days ago. He now regrets it and no longer wants to buy the motorbike. The money is still in his account. He asks his adviser whether he can take a new, cheaper loan to repay the first. What do you advise?", [["Point to the right of withdrawal, so that he is rid of the loan free of charge", "Within fourteen days he can withdraw and only repays the amount with the accrued interest."], ["Take out a new loan to repay the first loan in full immediately", "A new loan brings new costs and does not solve his regret about borrowing."], ["Repay early with a fee of 1% of the amount", "Within the withdrawal period, withdrawing without a fee is more favourable."], ["Wait until the end of the term and then look again", "That way he misses the chance to get out of the loan free of charge."]], "2e.1"],
["A client takes out payment protection insurance through an intermediary with their personal loan. May the intermediary receive commission for the payment protection insurance?", [["No, the commission ban applies to payment protection insurance", "The commission ban also covers payment protection insurance; the intermediary may not receive commission from the provider for it."], ["Yes, because commission on the associated loan is also permitted", "Commission is permitted for the credit itself, but a separate ban applies to payment protection insurance."], ["Only if the premium is lower than the interest on the loan", "The ratio between premium and interest plays no role in the commission ban."], ["Only if the payment protection insurance is with the same bank as the loan", "The ban applies regardless of with which party the payment protection insurance is placed."]], "3b.2"],
["An intermediary receives continuing commission for as long as a client's credit is outstanding. The client asks whether making extra repayments is wise. What is appropriate?", [["Advise what is in the client's interest, even if the commission falls", "The intermediary's own financial interest must not steer the advice."], ["Advise against it, because the intermediary's commission then decreases", "That puts the intermediary's interest above that of the client."], ["Refer them to the lender to avoid a conflict of interest", "Referring on evades the question; the intermediary must advise carefully themselves."], ["Allow extra repayments only in return for a fee for the intermediary", "The consumer has the right to repay; the intermediary cannot attach a condition to that."]], "2e.2"],
["A lender approves an application for €20,000.00 for €14,000.00, with the same term. What does the adviser discuss with the client first?", [["Why the amount is lower and whether the borrowing purpose remains achievable", "The client must understand why the lender is providing less and what that means for their plans."], ["How the client can borrow the difference from a second provider", "Borrowing the difference elsewhere circumvents the assessment and can lead to over-indebtedness."], ["That the client must sign the quote within a day", "Haste is not in the client's interest; they must first understand the outcome."], ["That a longer term would still make €20,000.00 possible", "That is not a given and can needlessly increase the total costs and the risk."]], "3c.1"],
["Why is a remuneration scheme with bonuses per credit granted problematic for credit sales staff?", [["It can encourage selling credit that does not suit the client", "Remuneration that rewards volume can lead to over-indebtedness and conflicts with careful service."], ["Because such bonuses are not tax deductible for the employer as business costs", "The tax treatment of bonuses is not the objection from the client's-interest point of view."], ["Because bonuses in the financial sector are completely prohibited", "There is no complete ban on variable remuneration; restrictions do apply."], ["Because BKR must register those bonuses per employee", "BKR does not register employees' remuneration."]], "1a.1"],
["Wim and Petra Jansen (both 50) want a personal loan together. Their joint net income is €4,200.00 per month and their rent is €1,100.00. For their household the credit provider uses a standard amount for living expenses of €2,300.00. They have no other fixed charges. How much room do they have at most for a monthly instalment according to this calculation?", [["€800.00", "Net income minus housing costs minus the standard amount: €4,200.00 - €1,100.00 - €2,300.00 = €800.00."], ["€1,900.00", "Here the rent has not been deducted; housing costs actually reduce the room."], ["€3,100.00", "Here the standard amount for living expenses has not been deducted."], ["€1,100.00", "That is the amount of the rent, not the room for a monthly instalment."]], "1h.5"],
["Must a new lender reassess creditworthiness when refinancing a loan?", [["Yes, a new credit requires its own creditworthiness assessment", "When refinancing, a new agreement is concluded; the new lender must assess the client's current situation."], ["No, the original lender's assessment remains valid for the new loan", "That assessment concerned an earlier situation and a different provider."], ["Only if the new credit amount is higher than the old one", "Even with an equal or lower amount it is a new credit that must be assessed."], ["No, refinancing falls outside the Wft", "Refinancing is simply entering into a new credit to which the Wft applies."]], "1b.2"],
["A client wants to fold their personal loan into an increase of their mortgage with a term of thirty years. Which disadvantage should the adviser discuss?", [["The debt runs much longer, so total interest may turn out higher", "A lower interest rate over a much longer period can turn out more expensive on balance; moreover the home serves as security."], ["Mortgage interest is always higher than the interest on a personal loan", "Mortgage interest is often actually lower; the disadvantage lies in the term."], ["A mortgage increase may never be used for repaying loans", "It is permitted, although it gives no interest deduction for that part."], ["After refinancing, the old loan remains in the BKR as outstanding", "A repaid loan is reported as ended; that is not an inherent disadvantage."]], "3b.3"],
["How is a personal loan for a holiday treated for tax purposes?", [["As a debt in box 3 above a threshold; the interest is not deductible", "Consumption debts can reduce assets in box 3, but the interest gives no deduction in box 1."], ["The interest is deductible in box 1, just like the interest on a mortgage for the own home", "Only interest on owner-occupied home debt is deductible in box 1; a holiday loan is not."], ["The loan counts nowhere for tax purposes", "The debt can count in box 3, if it exceeds the threshold."], ["The interest is deductible in box 2 as income from a substantial interest", "Box 2 concerns a substantial interest in a company, not private loans."]], "1g.1"],
["Wouter (43) owns a home with a mortgage. He has his roof renewed for €15,000.00 and takes out an annuity personal loan for it, without a mortgage right. The loan has a term of ten years. He asks whether he can deduct the interest. Can the interest be tax deductible?", [["Yes, if the loan meets the requirements for owner-occupied home debt (eigenwoningschuld)", "A loan for improving the own home can be owner-occupied home debt, even without a mortgage right, provided, among other things, the repayment requirement is met."], ["No, interest on a loan without a mortgage right on the home is never deductible", "For owner-occupied home debt the spending purpose and the repayment are decisive, not the mortgage right."], ["Yes, the interest on every personal loan is deductible", "Only a loan for the own home that meets the conditions gives interest deduction."], ["Only if the renovation is completed within one month of the loan", "Such a one-month period is not a condition for interest deduction."]], "1g.1"],
["Why can using buy now pay later several times at once be problematic for a consumer?", [["The overview of payments is quickly lost, with a risk of arrears", "Many small payments add up unnoticed; a missed instalment can lead to reminders and collection costs."], ["Because BNPL purchases are always taken out at a high fixed interest rate", "BNPL is often interest-free if paid on time; the risk lies in the accumulation."], ["Because every BNPL purchase leads immediately to a negative registration at BKR", "A purchase does not lead to a negative registration; that happens at most with arrears."], ["Because it is prohibited by law to have more than one BNPL purchase", "There is no statutory prohibition on multiple BNPL purchases."]], "1c.2"],
["A client with a revolving credit sees that their monthly instalment consists largely of interest. What is the consequence?", [["The debt falls slowly and the credit continues for a long time", "If mainly interest is paid, little goes to repayment and the debt remains in place for a long time."], ["The debt falls faster than with a personal loan", "Little repayment per instalment actually means a slow fall in the debt."], ["The interest lapses automatically after a year without drawings", "There is no rule under which interest lapses after a year."], ["The lender must write off the remainder after five years", "There is no mandatory write-off after a fixed period."]], "1h.3"],
["Credit intermediary Yusuf is working on the application of Mirjam (41), single and working as a doctor's assistant. In December 2026 Mirjam wants a €10,000 revolving credit to buy a car. The creditworthiness assessment shows that she probably cannot bear the monthly costs on her current income and fixed charges. Mirjam says she wants to take the risk herself and asks Yusuf to submit the application anyway. What applies from 20 November 2026 under the revised Consumer Credit Directive (CCD II)?", [["Only if the assessment shows that she is likely to be able to meet her obligations", "CCD II tightens the creditworthiness assessment: if it is negative, the lender may in principle not grant the credit, not even at the client's request."], ["The credit may be granted if Mirjam states in writing that she bears the risk herself", "A client's statement does not make good a negative creditworthiness assessment; the assessment is precisely intended to prevent over-indebtedness."], ["The credit may be granted if Mirjam has no negative BKR registration", "A clean BKR record is only one element; the assessment also looks at income, fixed charges and the new monthly cost."], ["After 20 November 2026 the creditworthiness assessment is only mandatory for credits above €75,000", "Under CCD II more credit falls under the rules, and the assessment remains mandatory for every credit that falls under the directive."]], "1h.5"],
["The online shop Fietsplein offers customers the option to pay only after thirty days. Fietsplein does not carry this out itself: an external pay-later provider takes over the claim and the customer pays that provider. No interest is charged, but a fee is charged for late payment. A customer asks whether this falls under the new rules for consumer credit. What is correct from 20 November 2026?", [["Yes, pay-later through an external provider falls under CCD II", "CCD II brings pay-later (BNPL) via a third party under the directive; the exemption for deferred payment only applies if the seller offers it itself without a third party."], ["No, pay-later without interest never falls under the rules for consumer credit", "Under CCD II interest-free credit via an external provider also falls under the directive; the absence of interest is not decisive."], ["No, because the customer pays within three months and there is no interest", "With pay-later via an external provider, a short period without interest does not exempt the credit under CCD II."], ["Only if the purchase amount is higher than €1,000", "CCD II actually lowers the lower threshold; small amounts can also fall under the directive."]], "1a.2"],
["A colleague reads that on 6 October 2026 the House of Representatives passed the bill for CCD II and thinks the Dutch rules therefore already apply. What is correct?", [["No, the Senate still has to consider the bill; entry into force then follows by royal decree", "A bill only becomes law after both Houses have dealt with it. After the House of Representatives passes it, the Senate is next; the entry into force is then set by royal decree."], ["Yes, once the House of Representatives has passed it, the act applies immediately", "Passage in the House of Representatives is not the end point; the Senate still has to consider the bill."], ["No, the act only applies after the European Commission has approved it", "The European Commission does not approve the Dutch implementation act; the legislative process runs through the House of Representatives and the Senate."], ["Yes, because the Senate only assesses the implementation costs", "The Senate fully reviews the bill and can pass or reject it, so it is not yet law."]], "1a.2"],
["A seventeen-year-old wants to pay later (BNPL) at a web shop via an external provider. What does the bill implementing CCD II, as passed by the House of Representatives, provide?", [["A ban on BNPL credit to minors, with mandatory age verification", "The bill bans BNPL credit to minors and requires providers to verify age. The final text follows after the Senate has considered it."], ["A parent's consent is sufficient to obtain BNPL credit", "The bill has no consent route: BNPL credit to minors is banned."], ["Nothing, because pay-later falls outside the consumer credit rules", "Under CCD II, pay-later via an external provider does fall under the credit regime."], ["Only a warning text in the web shop, no ban", "The bill goes further than a warning: it bans BNPL credit to minors."]], "1a.2"],
["A bank wants to give a customer a credit card with a credit limit. What is correct under CCD II?", [["The provider must first assess whether the customer is likely to be able to meet their obligations", "CCD II brings credit cards and overdrafts, among other things, under the credit regime, with a mandatory creditworthiness assessment before credit is granted."], ["Credit cards fall outside consumer credit, so no assessment is needed", "Credit cards with a credit facility fall under consumer credit and under CCD II."], ["The assessment is only needed if the customer asks for it", "The creditworthiness assessment is a duty of the provider, not a service on request."], ["The assessment applies only to the first application and never to an increase of the limit", "A new assessment is also needed for a significant increase of the credit amount."]], "1a.2"],
["A new company offers web shops pay-later and acts as an intermediary between consumer and credit provider. What does the bill implementing CCD II provide for provider and intermediary?", [["A licence or registration requirement for both the provider and the intermediary", "The bill provides for a licence or registration requirement for providers and intermediaries of these credits. The final text follows after the Senate has considered it."], ["Only the provider needs a licence; the intermediary is exempt", "The bill also provides for a licence or registration requirement for the intermediary."], ["Neither, as long as no interest is charged", "The absence of interest does not take BNPL out of the CCD II credit regime."], ["Only a notification to the Chamber of Commerce", "A Chamber of Commerce registration does not replace the licence or registration requirement."]], "1a.2"]
];
